window.STUDY_SEARCH={"courses":[{"slug":"american-painting","name":"American Painting","home":"/study/art-history/american-painting.html","img":"/study/art-history/american-painting/img/","lane":"Art history"},{"slug":"american-scene","name":"American Scene, 1930s","home":"/study/art-history/american-scene.html","img":"/study/art-history/american-scene/img/","lane":"Art history"},{"slug":"art-nouveau","name":"Art Nouveau and the Vienna Secession","home":"/study/art-history/art-nouveau.html","img":"/study/art-history/art-nouveau/img/","lane":"Art history"},{"slug":"baroque","name":"Baroque","home":"/study/art-history/baroque.html","img":"/study/art-history/baroque/img/","lane":"Art history"},{"slug":"birth-of-abstraction","name":"The Birth of Abstraction","home":"/study/art-history/birth-of-abstraction.html","img":"/study/art-history/birth-of-abstraction/img/","lane":"Art history"},{"slug":"classical-myth","name":"Classical Myth in Art","home":"/study/art-history/classical-myth.html","img":"/study/art-history/classical-myth/img/","lane":"Art history"},{"slug":"color-theory","name":"Color Theory","home":"/study/color-theory.html","img":"/study/color-theory/img/","lane":"Technique"},{"slug":"composition","name":"Composition","home":"/study/composition.html","img":"/study/composition/img/","lane":"Technique"},{"slug":"early-renaissance","name":"Early Renaissance in Italy","home":"/study/art-history/early-renaissance.html","img":"/study/art-history/early-renaissance/img/","lane":"Art history"},{"slug":"fauvism-and-expressionism","name":"Fauvism and Early Expressionism","home":"/study/art-history/fauvism-and-expressionism.html","img":"/study/art-history/fauvism-and-expressionism/img/","lane":"Art history"},{"slug":"high-renaissance","name":"High Renaissance","home":"/study/art-history/high-renaissance.html","img":"/study/art-history/high-renaissance/img/","lane":"Art history"},{"slug":"impressionism","name":"Impressionism","home":"/study/art-history/impressionism.html","img":"/study/art-history/impressionism/img/","lane":"Art history"},{"slug":"japanese-woodblock-prints","name":"Japanese Woodblock Prints","home":"/study/art-history/japanese-woodblock-prints.html","img":"/study/art-history/japanese-woodblock-prints/img/","lane":"Art history"},{"slug":"japonisme","name":"Japonisme","home":"/study/art-history/japonisme.html","img":"/study/art-history/japonisme/img/","lane":"Art history"},{"slug":"mannerism","name":"Mannerism","home":"/study/art-history/mannerism.html","img":"/study/art-history/mannerism/img/","lane":"Art history"},{"slug":"neoclassicism","name":"Neoclassicism","home":"/study/art-history/neoclassicism.html","img":"/study/art-history/neoclassicism/img/","lane":"Art history"},{"slug":"northern-renaissance","name":"Northern Renaissance","home":"/study/art-history/northern-renaissance.html","img":"/study/art-history/northern-renaissance/img/","lane":"Art history"},{"slug":"oil-vs-acrylic","name":"Oil vs Acrylic","home":"/study/oil-vs-acrylic.html","img":"/study/oil-vs-acrylic/img/","lane":"Technique"},{"slug":"pigments-and-materials","name":"Pigments and Materials","home":"/study/pigments-and-materials.html","img":"/study/pigments-and-materials/img/","lane":"Technique"},{"slug":"post-impressionism","name":"Post-Impressionism","home":"/study/art-history/post-impressionism.html","img":"/study/art-history/post-impressionism/img/","lane":"Art history"},{"slug":"realism","name":"Realism","home":"/study/art-history/realism.html","img":"/study/art-history/realism/img/","lane":"Art history"},{"slug":"rococo","name":"Rococo","home":"/study/art-history/rococo.html","img":"/study/art-history/rococo/img/","lane":"Art history"},{"slug":"romanticism","name":"Romanticism","home":"/study/art-history/romanticism.html","img":"/study/art-history/romanticism/img/","lane":"Art history"},{"slug":"value-and-light","name":"Value and Light","home":"/study/value-and-light.html","img":"/study/value-and-light/img/","lane":"Technique"}],"items":[[0,"/study/art-history/american-painting.html","American Painting · Overview","What to Look For","","homer-snap-the-whip","After the Civil War, many American painters found their subjects in their own country and its people: rowers, schoolchildren, and city streets. Hundreds of Americans also went to Paris to train, and some stayed to work there for years. In the first years of the 1900s, a group of New York painters, later called the Ashcan School, painted the crowded everyday life of the city in quick, loose brushwork. · Winslow Homer · Snap the Whip · 1872"],[0,"/study/art-history/american-painting/the-united-states-and-paris-1871-1909/the-champion-single-sculls-max-schmitt-in-a-single-scull.html","American Painting","The Champion Single Sculls (Max Schmitt in a Single Scull)","Thomas Eakins","eakins-champion-single-sculls","Thomas Eakins · 1871 · American, 1844–1916. Oil on canvas, 32 1/4 × 46 1/4 in. The Metropolitan Museum of Art, New York · Clear, low light picks out the scull and the trees, and the still river doubles them in sharp reflections. Near and far, every detail gets the same careful focus. · Eakins began painting rowers after he came home to Philadelphia from Europe in 1870, and this was the first major picture in that series; he painted himself rowing in the middle distance."],[0,"/study/art-history/american-painting/the-united-states-and-paris-1871-1909/madame-x-virginie-amelie-avegno-gautreau.html","American Painting","Madame X (Virginie Amélie Avegno Gautreau)","John Singer Sargent","sargent-madame-x","John Singer Sargent · 1883–84 · American, 1856–1925. Oil on canvas, 82 1/4 × 43 1/4 in. The Metropolitan Museum of Art, New York · Her pale skin stands out sharply against the black dress and the plain brown background, and her head turns into a crisp profile. · Shown at the Paris Salon of 1884, it drew more mockery than praise. Sargent then repainted the jeweled strap, which had first been shown slipping off her shoulder."],[0,"/study/art-history/american-painting/the-united-states-and-paris-1871-1909/the-annunciation.html","American Painting","The Annunciation","Henry Ossawa Tanner","tanner-annunciation","Henry Ossawa Tanner · 1898 · American, 1859–1937. Oil on canvas, 57 × 71 1/4 in. Philadelphia Museum of Art · A tall column of golden light stands in for the angel at the left, and its glow warms the plain room where Mary sits on a rumpled bed. · Painted soon after a trip to Egypt and Palestine, it was shown at the 1898 Paris Salon and bought the next year for the Philadelphia museum. It was the first of Tanner's works to enter an American museum."],[0,"/study/art-history/american-painting/the-united-states-and-paris-1871-1909/late-afternoon-new-york-winter.html","American Painting","Late Afternoon, New York, Winter","Childe Hassam","hassam-late-afternoon-winter","Childe Hassam · 1900 · American, 1859–1935. Oil on canvas, 37 × 29 in. Brooklyn Museum, New York · A haze of pale blue paint covers the street and melts the buildings into the snowy air, with small touches of pink and yellow for lamps and lit windows. · Hassam studied in Paris from 1886 to 1889, took up the Impressionists' bright color there, and then settled in New York, whose streets became a favorite subject."],[0,"/study/art-history/american-painting/the-united-states-and-paris-1871-1909/snow-in-new-york.html","American Painting","Snow in New York","Robert Henri","henri-snow-in-new-york","Robert Henri · 1902 · American, 1865–1929. Oil on canvas, 32 × 25 3/4 in. National Gallery of Art, Washington · Thick white strokes for the snow sit over thin, dark washes for the buildings that close in on both sides, and the brown-black ground shows through in places. · Signed and dated March 5, 1902, it hung that April in Henri's solo show at the Macbeth Gallery in New York, where only two of his pictures found buyers, this one among them."],[0,"/study/art-history/american-painting/the-united-states-and-paris-1871-1909/the-wake-of-the-ferry-ii.html","American Painting","The Wake of the Ferry II","John Sloan","sloan-wake-of-the-ferry-ii","John Sloan · 1907 · American, 1871–1951. Oil on canvas, 26 × 32 in. The Phillips Collection, Washington · Almost everything is painted in grays. The dark posts and roof of the ferry deck frame the gray water like a window, and a lone figure leans on the rail. · It is Sloan's second version of the subject; the first is in Detroit. Duncan Phillips bought this one in 1922."],[0,"/study/art-history/american-painting/the-united-states-and-paris-1871-1909/stag-at-sharkeys.html","American Painting","Stag at Sharkey's","George Bellows","bellows-stag-at-sharkeys","George Bellows · 1909 · American, 1882–1925. Oil on canvas, 36 1/4 × 48 1/4 in. The Cleveland Museum of Art · Bright light falls on the two fighters' straining bodies, while most of the crowd around the ring sinks into dark, rough strokes. · Boxing matches open to the public were banned in New York at the time, so Sharkey's Athletic Club staged bouts as private members' events, and an outsider who fought was made a temporary member, called a stag."],[1,"/study/art-history/american-scene.html","American Scene, 1930s · Overview","What to Look For","","wood-american-gothic","During the Great Depression, many American painters turned to the everyday life of their own country, a subject called the American Scene. In December 1933 the federal government began the Public Works of Art Project, the first federal program to support the arts across the whole country. Between then and June 1934 it employed thousands of artists, and their paintings became government property. · Grant Wood · American Gothic · 1930"],[1,"/study/art-history/american-scene/the-united-states-1930-1934/italians-in-jefferson-park.html","American Scene, 1930s","Italians in Jefferson Park","Jerome Myers","myers-jefferson-park","Jerome Myers · 1934 · American, 1867–1940. Oil on fiberboard, 25 × 30 in. Smithsonian American Art Museum, Washington · A crowd of fairgoers fills a park under umbrellas and red brick buildings, all in soft, chalky color. · He painted it in New York City. His autobiography, Artist in Manhattan, came out in 1940, the year he died."],[1,"/study/art-history/american-scene/the-united-states-1930-1934/mid-hudson-bridge-winter.html","American Scene, 1930s","Mid-Hudson Bridge--Winter","Cecil Chichester","chichester-mid-hudson-bridge","Cecil Chichester · 1934 · American, born 1891. Oil on canvas, 30 × 40 in. Smithsonian American Art Museum, Washington · A snowy road curves toward the bridge, and gray-violet tones in the snow, the hills, and the sky tie the winter scene together. · The bridge in the picture crosses the Hudson River at Poughkeepsie; it opened in 1930."],[1,"/study/art-history/american-scene/the-united-states-1930-1934/decoration.html","American Scene, 1930s","Decoration","Florence Standish Whiting","whiting-decoration","Florence Standish Whiting · about 1933–34 · American, 1888–1947. Oil on canvas, 30 1/4 × 47 1/4 in. Smithsonian American Art Museum, Washington · Women carry grapes, fruit, and flowers among slender trees, shown as simplified shapes in rich purples, reds, and blues. · Whiting, a Philadelphia painter, worked on the project in Pennsylvania."],[1,"/study/art-history/american-scene/the-united-states-1930-1934/employment-of-negroes-in-agriculture.html","American Scene, 1930s","Employment of Negroes in Agriculture","Earle Richardson","richardson-employment-agriculture","Earle Richardson · 1934 · American, 1912–1935. Oil on canvas, 48 × 32 1/4 in. Smithsonian American Art Museum, Washington · Large figures crowd the front of the picture against rows of cotton, painted with smooth, rounded forms in sharp light and deep shadow. · Of the thousands of artists on the project's rolls, only about ten were Black, and Richardson was one; he died the following year."],[1,"/study/art-history/american-scene/the-united-states-1930-1934/at-madrid-coal-mine-new-mexico.html","American Scene, 1930s","At Madrid Coal Mine, New Mexico","Carl Redin","redin-madrid-coal-mine","Carl Redin · 1934 · American, born in Sweden, 1892–1944. Oil on canvas, 30 × 38 in. Smithsonian American Art Museum, Washington · Boxy mine buildings climb the hillside in lavender and gray, and no people appear; a small train runs along the bottom. · Redin usually painted New Mexico landscapes, but to find the American Scene the project called for, he turned to the coal mines of Madrid, a town where the company owned the mines, the stores, and the houses."],[1,"/study/art-history/american-scene/the-united-states-1930-1934/gold-is-where-you-find-it.html","American Scene, 1930s","Gold Is Where You Find It","Tyrone Comfort","comfort-gold","Tyrone Comfort · 1934 · American, 1909–1939. Oil on canvas, 40 × 50 in. Smithsonian American Art Museum, Washington · A shirtless miner braces against a drill in a tight crevice beneath slanting slabs of rock. · President and Mrs. Roosevelt chose it to hang in the White House."],[1,"/study/art-history/american-scene/the-united-states-1930-1934/industry.html","American Scene, 1930s","Industry","Arthur Durston","durston-industry","Arthur Durston · 1934 · American, born in England, 1889–1938. Oil on canvas, 50 × 40 in. Smithsonian American Art Museum, Washington · Three stiff, elongated women stand in front of a factory town whose upright smokestacks repeat their vertical lines. · When the Depression was at its lowest point, over fifteen million Americans who wanted work could not find it."],[2,"/study/art-history/art-nouveau.html","Art Nouveau and the Vienna Secession · Overview","What to Look For","","mucha-gismonda","In the 1890s a new style spread across Europe through street posters, magazines, and books. Its artists drew long curving lines, flat areas of color, and patterns taken from plants. In Paris it took its name, Art Nouveau, from a shop that opened in 1895. In Vienna, artists who left the city's official exhibiting society in 1897 founded the Secession, with the painter Gustav Klimt as its first president. · Alphonse Mucha · Gismonda · 1895"],[2,"/study/art-history/art-nouveau/europe-1892-1909/encre-l-marquet.html","Art Nouveau and the Vienna Secession","Encre L. Marquet","Eugène Grasset","grasset-encre-l-marquet","Eugène Grasset · 1892 · Swiss-born, active in France, 1841–1917. Color lithograph, 47 1/4 × 32 in. Victoria and Albert Museum, London · Most shapes have a dark outline and are filled with flat yellow, orange, and gray. The wavy edges of the clouds repeat the waves of the woman's hair. · Made to advertise Marquet ink, this sheet came to the museum from the collection of Joseph Thacher Clarke, an early collector of posters."],[2,"/study/art-history/art-nouveau/europe-1892-1909/jai-baise-ta-bouche-iokanaan.html","Art Nouveau and the Vienna Secession","J'ai baisé ta bouche Iokanaan","Aubrey Beardsley","beardsley-jai-baise-ta-bouche-iokanaan","Aubrey Beardsley · 1893 · English, 1872–1898. Line-block print, 9 × 5 in. Victoria and Albert Museum, London · Only black ink and bare paper are used: solid black fills Salome's hair and the pool below, while thin lines draw her robe and the head of Iokanaan she holds up. · Reproduced in the first issue of The Studio magazine in April 1893, the drawing won Beardsley the commission to illustrate the English edition of Oscar Wilde's Salome, published in 1894."],[2,"/study/art-history/art-nouveau/europe-1892-1909/delftsche-slaolie.html","Art Nouveau and the Vienna Secession","Delftsche Slaolie","Jan Toorop","toorop-delftsche-slaolie","Jan Toorop · 1894 · Dutch, 1858–1928. Color lithograph, 37 1/2 × 24 1/2 in. Rijksmuseum, Amsterdam · The two women's hair runs in long, parallel wavy lines that fill most of the background. Strong dark outlines keep the women themselves standing out against it. · Made for the Nederlandsche Oliefabriek, an oil maker in Delft, the poster became so well known that the Dutch nicknamed Art Nouveau the “salad oil style.”"],[2,"/study/art-history/art-nouveau/europe-1892-1909/tournee-du-chat-noir.html","Art Nouveau and the Vienna Secession","Tournée du Chat Noir","Théophile-Alexandre Steinlen","steinlen-tournee-du-chat-noir","Théophile-Alexandre Steinlen · 1896 · Swiss-born, active in France, 1859–1923. Color lithograph, 55 × 39 in. Rijksmuseum, Amsterdam · One flat black cat sits on a red band against bare paper, with a red halo behind its head. Almost nothing is shaded, so the cat reads as a single bold shape. · Le Chat Noir was a cabaret in Montmartre, Paris; the poster announced the coming tour of its performers with Rodolphe Salis."],[2,"/study/art-history/art-nouveau/europe-1892-1909/job.html","Art Nouveau and the Vienna Secession","JOB","Alphonse Mucha","mucha-job","Alphonse Mucha · 1898 · Czech, 1860–1939. Color lithograph, 20 1/4 × 15 1/4 in. Victoria and Albert Museum, London · The woman's hair spreads across the sheet in thick golden curls that turn into pattern, and the O of the brand name rings her head like a halo. · It was printed in Paris by F. Champenois to advertise JOB cigarette papers."],[2,"/study/art-history/art-nouveau/europe-1892-1909/poster-for-the-fifth-secession-exhibition.html","Art Nouveau and the Vienna Secession","Poster for the Fifth Secession Exhibition","Koloman Moser","moser-fifth-secession-exhibition","Koloman Moser · 1899 · Austrian, 1868–1918. Color lithograph, 39 1/4 × 27 1/2 in. Wien Museum, Vienna · The word SECESSION at the top is drawn in the same thin pale line that outlines the figure, the leaves, and the hair, so lettering and picture read as one design. · It advertised the Vienna Secession's fifth exhibition, held in November and December 1899, and was printed in at least two color schemes, green and red."],[2,"/study/art-history/art-nouveau/europe-1892-1909/the-kiss.html","Art Nouveau and the Vienna Secession","The Kiss","Gustav Klimt","klimt-the-kiss","Gustav Klimt · 1908–09 · Austrian, 1862–1918. Oil and gold, silver, and platinum leaf on canvas, 70 3/4 × 70 3/4 in. Belvedere, Vienna · Her face, their hands, and her feet are painted as soft, rounded flesh, but their robes are flat fields of gold, patterned with rectangles on his and circles on hers. · First shown at the Kunstschau in Vienna in June 1908 under the title Lovers, it was bought there for the state's Moderne Galerie, now the Belvedere."],[3,"/study/art-history/baroque.html","Baroque · Overview","What to Look For","","caravaggio-supper-emmaus","The Baroque style took shape in Rome and spread across Europe in the 1600s, to Catholic churches and royal courts and to the Protestant Dutch Republic. Painters used strong contrasts of light and dark, bodies in motion, and figures pressed close to the viewer to make a scene feel real and immediate. · Caravaggio · The Supper at Emmaus · 1601"],[3,"/study/art-history/baroque/europe-1599-1694/the-calling-of-saint-matthew.html","Baroque","The Calling of Saint Matthew","Caravaggio","caravaggio-calling-matthew","Caravaggio · 1599–1600 · Italian, 1571–1610. Oil on canvas, about 126 3/4 × 133 3/4 in. Contarelli Chapel, San Luigi dei Francesi, Rome · A single beam of light cuts across the dark room from the upper right and falls on the tax collectors at their table, while Christ, half hidden behind Peter, points toward Matthew. The men at the table wear the everyday clothes of Caravaggio's Rome. · Caravaggio signed the contract in July 1599. It was his first major public commission, one of three paintings of Saint Matthew for the same chapel, where it still hangs."],[3,"/study/art-history/baroque/europe-1599-1694/the-elevation-of-the-cross.html","Baroque","The Elevation of the Cross","Peter Paul Rubens","rubens-elevation-cross","Peter Paul Rubens · 1609–10 · Flemish, 1577–1640. Oil on panel, center panel 181 × 133 3/4 in. Cathedral of Our Lady, Antwerp · Muscular men heave the cross upward on one steep diagonal. The rocky ground runs from the left wing into the center and the darkening sky into the right wing, so the three panels read as one scene. · Made for the high altar of Antwerp's church of Saint Walburga, since destroyed, it was Rubens's first major commission after his return from Italy."],[3,"/study/art-history/baroque/europe-1599-1694/judith-beheading-holofernes.html","Baroque","Judith Beheading Holofernes","Artemisia Gentileschi","gentileschi-judith-uffizi","Artemisia Gentileschi · about 1620 · Italian, 1593–1652 or 1653. Oil on canvas, 78 1/4 × 64 in. The Uffizi, Florence · The three figures are cropped close and pushed right up to the front of the picture, and their arms lock together at the center, around the sword. · Made for Grand Duke Cosimo II de' Medici, it drew strong reactions in Florence and was denied a place in the Uffizi Gallery. Her friend Galileo helped her collect the late payment."],[3,"/study/art-history/baroque/europe-1599-1694/christ-in-the-storm-on-the-sea-of-galilee.html","Baroque","Christ in the Storm on the Sea of Galilee","Rembrandt","rembrandt-storm-galilee","Rembrandt · 1633 · Dutch, 1606–1669. Oil on canvas, 63 × 50 1/2 in. Isabella Stewart Gardner Museum, Boston · A wave lifts the bow high on a steep tilt into a break of light in the clouds, while the back of the boat sinks into shadow. · Thieves stole it from the museum on March 18, 1990, cutting it from its frame; twelve other works were taken with it. It is still missing."],[3,"/study/art-history/baroque/europe-1599-1694/las-meninas.html","Baroque","Las Meninas","Diego Velázquez","velazquez-las-meninas","Diego Velázquez · 1656 · Spanish, 1599–1660. Oil on canvas, 126 1/4 × 110 3/4 in. Museo del Prado, Madrid · Light from the right falls across the figures, and the room runs back to a bright open door. The mirror on the back wall shows the king and queen. · Velázquez painted himself at his easel at the left. The red cross of the Order of Santiago on his chest seems to have been added after his death."],[3,"/study/art-history/baroque/europe-1599-1694/the-milkmaid.html","Baroque","The Milkmaid","Johannes Vermeer","vermeer-milkmaid","Johannes Vermeer · about 1660 · Dutch, 1632–1675. Oil on canvas, 18 × 16 1/4 in. Rijksmuseum, Amsterdam · Daylight from the window at the left falls on a woman standing as still as a statue; only the stream of milk moves. Small dots of pale paint make the bread and basket glint. · Sold at auction in Amsterdam in 1696 for 175 guilders, it was bought for the Rijksmuseum in 1908 with help from the Rembrandt Association."],[3,"/study/art-history/baroque/europe-1599-1694/the-glory-of-saint-ignatius.html","Baroque","The Glory of Saint Ignatius","Andrea Pozzo","pozzo-sant-ignazio","Andrea Pozzo · 1691–94 · Italian, 1642–1709. Fresco, painted vault about 131 × 59 ft. Sant'Ignazio, Rome · Painted columns and arches carry the real walls upward, so the vault seems to open onto a sky where saints and angels rise toward Christ. · Pozzo, himself a Jesuit, explained the ceiling's meaning in a 1694 letter to the Prince of Liechtenstein. A disc in the nave floor marks the spot where the illusion works."],[4,"/study/art-history/birth-of-abstraction.html","The Birth of Abstraction · Overview","What to Look For","","kandinsky-improvisation-30","In the early 1900s, painters in several countries began to give up depicting the things they saw. Some built on the broken-up forms of Cubism; others started from spiritual ideas, from music, or from nature. By the 1920s, color, line, and shape could be the whole subject of a painting. · Wassily Kandinsky · Improvisation No. 30 (Cannons) · 1913"],[4,"/study/art-history/birth-of-abstraction/europe-and-the-united-states-1907-1925/the-ten-largest-group-iv-no-7-adulthood.html","The Birth of Abstraction","The Ten Largest, Group IV, No. 7, Adulthood","Hilma af Klint","af-klint-ten-largest-7","Hilma af Klint · 1907 · Swedish, 1862–1944. Tempera on paper mounted on canvas, about 124 × 92 1/2 in. The Hilma af Klint Foundation, Stockholm · Huge, flat shapes in yellow, green, and red float on a lilac ground among spirals, petals, and looping script, and none of them adds up to a scene. · Each sheet of the series took about four days, laid on the floor as she painted. She asked that her abstract work not be shown publicly for twenty years after her death, and it reached a wide public only in 1986."],[4,"/study/art-history/birth-of-abstraction/europe-and-the-united-states-1907-1925/sails.html","The Birth of Abstraction","Sails","Arthur Dove","dove-sails","Arthur Dove · 1911–12 · American, 1880–1946. Pastel on composition board mounted on wood panel, 17 3/4 × 21 1/2 in. Terra Foundation for American Art, Chicago · Tall, pointed tan shapes curve up across the picture like sails against dark green and blue, but the boats and the water are never clearly drawn. · One of ten pastels later called the Ten Commandments, it was shown at Alfred Stieglitz's gallery 291 in New York in 1912 and then in Chicago."],[4,"/study/art-history/birth-of-abstraction/europe-and-the-united-states-1907-1925/windows-open-simultaneously-1st-part-3rd-motif.html","The Birth of Abstraction","Windows Open Simultaneously 1st Part, 3rd Motif","Robert Delaunay","delaunay-windows-open-simultaneously","Robert Delaunay · 1912 · French, 1885–1941. Oil on canvas, about 22 1/2 × 48 1/2 in. Peggy Guggenheim Collection, Venice · Planes of clear color overlap across the oval canvas, and changes of color, not drawn lines, separate one plane from the next. A green Eiffel Tower, reduced to a dark spire, still stands at the center. · In the spring of 1912 Delaunay began the Windows series, which carried him toward painting with no recognizable subject."],[4,"/study/art-history/birth-of-abstraction/europe-and-the-united-states-1907-1925/suprematist-composition-airplane-flying.html","The Birth of Abstraction","Suprematist Composition: Airplane Flying","Kazimir Malevich","malevich-airplane-flying","Kazimir Malevich · 1915 · Born in Kyiv, then part of the Russian Empire, 1878–1935. Oil on canvas, 22 3/4 × 19 in. The Museum of Modern Art, New York · Black, yellow, red, and blue rectangles slant across a white field, with no horizon or cast shadow to anchor them. · Malevich introduced Suprematism, his name for this kind of painting, in December 1915 at the 0.10 exhibition in Petrograd."],[4,"/study/art-history/birth-of-abstraction/europe-and-the-united-states-1907-1925/architectonic-painting.html","The Birth of Abstraction","Architectonic Painting","Lyubov Popova","popova-architectonic-painting","Lyubov Popova · 1917 · Russian, 1889–1924. Oil on canvas, 33 × 24 1/4 in. Los Angeles County Museum of Art · Sharp-edged planes of orange, red, green, blue, and white crowd together at angles, and shading along their edges makes them look like solid slabs stacked in space. · Popova called these paintings “Painterly Architectonics” after she joined Malevich's Supremus group in 1916."],[4,"/study/art-history/birth-of-abstraction/europe-and-the-united-states-1907-1925/composition-with-large-blue-plane-red-black-yellow-and-gray.html","The Birth of Abstraction","Composition with Large Blue Plane, Red, Black, Yellow, and Gray","Piet Mondrian","mondrian-large-blue-plane","Piet Mondrian · 1921 · Dutch, 1872–1944. Oil on canvas, 23 3/4 × 19 3/4 in. Dallas Museum of Art · Black lines divide the canvas into unequal rectangles: a large blue area fills the upper right, a red strip and a black block sit at the lower left, and a small yellow block touches the bottom edge. · By 1921 Mondrian had set himself strict limits: lines ran only upright or level, and color was only red, yellow, and blue, with white, black, and gray as neutrals."],[4,"/study/art-history/birth-of-abstraction/europe-and-the-united-states-1907-1925/may-picture.html","The Birth of Abstraction","May Picture","Paul Klee","klee-may-picture","Paul Klee · 1925 · German, born in Switzerland, 1879–1940. Oil on cardboard, 16 1/2 × 19 1/2 in. The Metropolitan Museum of Art, New York · Small squares in many shades of color fill the board from edge to edge, so the surface reads like a mosaic that could go on past the frame. · Klee's Magic Square series traces back to a 1914 trip to Tunisia, and his study of color also shaped his teaching at the Bauhaus."],[5,"/study/art-history/classical-myth.html","Classical Myth in Art · Overview","What to Look For","","h9_bacchus","The gods and heroes of Greece and Rome have been painted and carved for more than 2,500 years. Each age told the same stories in its own way, from Athenian vase painters to the Renaissance, the Baroque, and the 1800s. · Caravaggio · Bacchus · about 1598"],[5,"/study/art-history/classical-myth/greece-to-paris-515-bce-1864/krater-with-heracles-wrestling-antaeus.html","Classical Myth in Art","Krater with Heracles Wrestling Antaeus","Euphronios","h12_antaios","Euphronios · about 515–510 BCE · Athenian painter, 6th–5th century BCE. Red-figure terracotta, 18 in. high. Louvre, Paris · In red-figure painting the figures are left the color of the clay and the background is painted black. Euphronios drew Heracles and the giant Antaeus in fine dark lines, so muscles and ribs show inside each wrestling body. · Made in Athens and later found in Etruria, in central Italy. Heracles kneels and strangles Antaeus while women flee to either side."],[5,"/study/art-history/classical-myth/greece-to-paris-515-bce-1864/venus-de-milo.html","Classical Myth in Art","Venus de Milo","Greek, sculptor unknown","h6_milo","Greek, sculptor unknown · about 150–125 BCE · Parian marble, 80 1/4 in. high. Louvre, Paris · Aphrodite, the goddess of love (Venus to the Romans), turns her hips one way and her head another, so the body twists in a slow spiral instead of standing straight. · Found on the island of Melos in 1820. It was carved in two blocks of marble joined at the hips, and the left arm and most of the right are lost."],[5,"/study/art-history/classical-myth/greece-to-paris-515-bce-1864/the-birth-of-venus.html","Classical Myth in Art","The Birth of Venus","Sandro Botticelli","h1_aphrodite","Sandro Botticelli · about 1485 · Italian, 1445–1510. Tempera on canvas, 68 × 109 3/4 in. Uffizi Gallery, Florence · Venus comes ashore on a scallop shell, blown by the winds. Botticelli edged every figure with a clean, flowing line and shaded the skin only faintly, so the bodies look nearly flat. · Probably a Medici commission. Canvas was then a common support for decorations in grand houses. Vasari described it in 1550 at the Medici villa of Castello."],[5,"/study/art-history/classical-myth/greece-to-paris-515-bce-1864/diana-and-actaeon.html","Classical Myth in Art","Diana and Actaeon","Titian","h6_actaeon","Titian · 1556–59 · Italian, about 1488–1576. Oil on canvas, 72 3/4 × 79 1/2 in. The National Gallery, London, and National Galleries of Scotland · The hunter Actaeon pulls back a red curtain and comes upon the goddess Diana bathing. Titian built the bodies and cloth from soft, loose strokes of warm color, without hard outlines. · One of six paintings of Ovid's myths, the poesie, made for Philip II of Spain. The stag's skull on the stone pillar foretells Actaeon's fate: Diana turns him into a stag."],[5,"/study/art-history/classical-myth/greece-to-paris-515-bce-1864/the-judgement-of-paris.html","Classical Myth in Art","The Judgement of Paris","Peter Paul Rubens","h15_paris","Peter Paul Rubens · probably 1632–35 · Flemish, 1577–1640. Oil on panel, probably oak, 57 × 76 1/4 in. The National Gallery, London · The shepherd Paris must give a golden apple to the most beautiful of three goddesses. Rubens set their pale, warm bodies against dark trees and showed each from a different side: front, side, and back. · Paris hands the apple to Venus, in the middle; Minerva's owl sits in the tree at left, and Juno's peacock stands at her feet. The National Gallery bought it in 1844."],[5,"/study/art-history/classical-myth/greece-to-paris-515-bce-1864/oedipus-explains-the-riddle-of-the-sphinx.html","Classical Myth in Art","Oedipus Explains the Riddle of the Sphinx","Jean-Auguste-Dominique Ingres","h14_ingres","Jean-Auguste-Dominique Ingres · 1808 · French, 1780–1867. Oil on canvas, 74 1/2 × 56 3/4 in. Louvre, Paris · Oedipus answers the riddle of the Sphinx, a monster that killed those who failed it. Ingres drew him in strict profile with one smooth, unbroken outline and no visible brushwork, lit like a statue against a dark cave. · Sent to Paris in 1808 as student work from the French Academy in Rome, probably retouched later, and shown at the Salon of 1827."],[5,"/study/art-history/classical-myth/greece-to-paris-515-bce-1864/oedipus-and-the-sphinx.html","Classical Myth in Art","Oedipus and the Sphinx","Gustave Moreau","h18_moreau","Gustave Moreau · 1864 · French, 1826–1898. Oil on canvas, 81 1/4 × 41 1/4 in. The Metropolitan Museum of Art, New York · Moreau painted the same story 56 years after Ingres, with the Sphinx now clinging to Oedipus's chest. He gave every feather, jewel, and bead a sharp edge, so small details hold the eye across the whole canvas. · It won Moreau wide notice when it was shown at the Paris Salon of 1864."],[6,"/study/color-theory.html","Color Theory","Color Theory","","runge-farbenkugel","Modern color theory starts with Isaac Newton's Opticks (1704) and his prism. Goethe, the chemist Chevreul, and the teacher Munsell then asked a painter's questions: how colors change beside each other, and how to name them exactly."],[6,"/study/color-theory/light-paint-and-the-eye/color-comes-from-light.html","Color Theory","Color Comes from Light","","newton-opticks-circle","Color begins as light. White sunlight already holds every color, and a glass prism bends each one by a different amount, spreading them into a band, the spectrum. · Claude Monet · Rouen Cathedral, West Façade · 1894 · Monet painted this front more than thirty times; here the stone is pale blue, lavender, and peach, colors of one light and weather, not of the stone."],[6,"/study/color-theory/light-paint-and-the-eye/color-comes-from-light.html","Color Theory · Example","Rouen Cathedral, West Façade","Claude Monet","thumb/monet-rouen-west-facade","1894 · Monet painted this front more than thirty times; here the stone is pale blue, lavender, and peach, colors of one light and weather, not of the stone. · Color Comes from Light"],[6,"/study/color-theory/light-paint-and-the-eye/mixing-light-and-mixing-paint.html","Color Theory","Mixing Light and Mixing Paint","","bezold-plate-i-mixtures","Mixing light adds colors together; mixing paint takes light away, so paint mixtures turn darker and duller. · Titian · Bacchus and Ariadne · 1520–23 · Titian laid his pigments on nearly pure and lightened them only with white, so the ultramarine sky keeps the strength a mixture would lose."],[6,"/study/color-theory/light-paint-and-the-eye/mixing-light-and-mixing-paint.html","Color Theory · Example","Bacchus and Ariadne","Titian","thumb/titian-bacchus-ariadne","1520–23 · Titian laid his pigments on nearly pure and lightened them only with white, so the ultramarine sky keeps the strength a mixture would lose. · Mixing Light and Mixing Paint"],[6,"/study/color-theory/light-paint-and-the-eye/hue-value-and-saturation.html","Color Theory","Hue, Value, and Saturation","","ostwald-farbenfibel-triangle","Three things pin down any color: hue (red, yellow, blue, and so on), value (how light or dark) and saturation (how strong or grayed). Each can change while the others hold. · Sassoferrato · The Virgin in Prayer · 1640–50 · Sassoferrato kept the mantle one ultramarine blue; only its value moves, from bright folds to deep navy shadow, and that alone gives the cloth depth."],[6,"/study/color-theory/light-paint-and-the-eye/hue-value-and-saturation.html","Color Theory · Example","The Virgin in Prayer","Sassoferrato","thumb/sassoferrato-virgin-prayer","1640–50 · Sassoferrato kept the mantle one ultramarine blue; only its value moves, from bright folds to deep navy shadow, and that alone gives the cloth depth. · Hue, Value, and Saturation"],[6,"/study/color-theory/light-paint-and-the-eye/the-color-wheel.html","Color Theory","The Color Wheel","","chevreul-chromatic-circle","A color wheel bends the hues into a circle, so neighbors and opposites can be read at a glance. · Paul Signac · Evening Calm, Concarneau, Opus 220 (Allegro Maestoso) · 1891 · Signac took his shadows from across the wheel: yellow-orange evening light on the hill, violet-blue on the rocks, so lit and shaded ground stand clearly apart."],[6,"/study/color-theory/light-paint-and-the-eye/the-color-wheel.html","Color Theory · Example","Evening Calm, Concarneau, Opus 220 (Allegro Maestoso)","Paul Signac","thumb/signac-evening-calm","1891 · Signac took his shadows from across the wheel: yellow-orange evening light on the hill, violet-blue on the rocks, so lit and shaded ground stand clearly apart. · The Color Wheel"],[6,"/study/color-theory/light-paint-and-the-eye/warm-and-cool.html","Color Theory","Warm and Cool","","field-chromatography-fig-2","Reds, oranges, and yellows read as warm, like fire and sunlight, and blues, greens, and violets as cool, like water and shade, though any color is warmer or cooler only beside another. · Joseph Mallord William Turner · The Fighting Temeraire · 1839 · Turner splits the sky between a blazing orange sunset on the right and cool blue on the left; each half looks warmer or cooler beside the other."],[6,"/study/color-theory/light-paint-and-the-eye/warm-and-cool.html","Color Theory · Example","The Fighting Temeraire","Joseph Mallord William Turner","thumb/turner-temeraire","1839 · Turner splits the sky between a blazing orange sunset on the right and cool blue on the left; each half looks warmer or cooler beside the other. · Warm and Cool"],[6,"/study/color-theory/light-paint-and-the-eye/complementary-colors.html","Color Theory","Complementary Colors","","chevreul-1890-plate-i","Complementary colors sit directly across the wheel: red and green, orange and blue, yellow and violet. Side by side each makes the other look stronger; mixed as paint they dull each other. · Vincent van Gogh · The Night Café · 1888 · Van Gogh set blood-red walls against a green ceiling and billiard table; the opposites heighten each other into a clash he meant to feel harsh."],[6,"/study/color-theory/light-paint-and-the-eye/complementary-colors.html","Color Theory · Example","The Night Café","Vincent van Gogh","thumb/vangogh-night-cafe","1888 · Van Gogh set blood-red walls against a green ceiling and billiard table; the opposites heighten each other into a clash he meant to feel harsh. · Complementary Colors"],[6,"/study/color-theory/light-paint-and-the-eye/analogous-colors.html","Color Theory","Analogous Colors","","chevreul-1890-plate-vi-detail","Analogous colors are neighbors on the wheel, such as yellow, yellow-green, and green. Each shares some of the next one's color, so they look calm together. · Claude Monet · Water Lilies (Agapanthus) · c. 1915–26 · Monet kept the pond to violets, blues, and greens, neighbors that blend into one continuous surface; a few pale lily pads and warm blossoms break the run."],[6,"/study/color-theory/light-paint-and-the-eye/analogous-colors.html","Color Theory · Example","Water Lilies (Agapanthus)","Claude Monet","thumb/monet-water-lilies-agapanthus","c. 1915–26 · Monet kept the pond to violets, blues, and greens, neighbors that blend into one continuous surface; a few pale lily pads and warm blossoms break the run. · Analogous Colors"],[6,"/study/color-theory/light-paint-and-the-eye/simultaneous-contrast.html","Color Theory","Simultaneous Contrast","","chevreul-1890-plate-ii","A color changes with its surroundings: the eye pushes it toward the opposite of its neighbor, in hue and lightness, so one paint looks different on different grounds, or backgrounds. · Vincent van Gogh · Irises · 1889 · Van Gogh set blue-violet irises against orange flowers and green leaves against red earth, so each color makes its neighbor look stronger."],[6,"/study/color-theory/light-paint-and-the-eye/simultaneous-contrast.html","Color Theory · Example","Irises","Vincent van Gogh","thumb/vangogh-irises-getty","1889 · Van Gogh set blue-violet irises against orange flowers and green leaves against red earth, so each color makes its neighbor look stronger. · Simultaneous Contrast"],[6,"/study/color-theory/light-paint-and-the-eye/optical-mixing.html","Color Theory","Optical Mixing","","chevreul-1890-plate-x","Small touches of two colors side by side blend in the eye into a third, because from a distance the eye can no longer tell them apart. · Henri-Edmond Cross · Pines Along the Shore · 1896 · Cross laid the shore in separate dabs of orange, pink, and violet; from a step back they merge into warm, sunlit ground."],[6,"/study/color-theory/light-paint-and-the-eye/optical-mixing.html","Color Theory · Example","Pines Along the Shore","Henri-Edmond Cross","thumb/cross-pines-shore","1896 · Cross laid the shore in separate dabs of orange, pink, and violet; from a step back they merge into warm, sunlit ground. · Optical Mixing"],[6,"/study/color-theory/light-paint-and-the-eye/local-and-expressive-color.html","Color Theory","Local and Expressive Color","","marc-blue-horse-i","Local color is a thing's color in plain daylight; expressive color is chosen for feeling or design instead. A tree or a hill can still be read by its shape, which leaves the color free. · Paul Gauguin · Mahana no atua (Day of the God) · 1894 · Gauguin painted this in Paris from memory and fantasy: a pink bank and water in flat zones of yellow, blue, and violet that still read as bank and water."],[6,"/study/color-theory/light-paint-and-the-eye/local-and-expressive-color.html","Color Theory · Example","Mahana no atua (Day of the God)","Paul Gauguin","thumb/gauguin-day-of-god","1894 · Gauguin painted this in Paris from memory and fantasy: a pink bank and water in flat zones of yellow, blue, and violet that still read as bank and water. · Local and Expressive Color"],[7,"/study/composition.html","Composition","Composition","","poore-picture-vision","Composition is how a painter arranges the parts of a picture. In 1435 Leon Battista Alberti named it one of three parts of a painter's job and compared the picture to an open window. In his 1899 book Composition, the American teacher Arthur Wesley Dow drew heavily on Japanese art, with line, dark-and-light, and color as its elements."],[7,"/study/composition/arranging-a-picture/format.html","Composition","Format","","dow-three-proportions","Format is the outline of the whole picture: tall, wide, square, or round. It decides how much room each part of the subject gets, so one scene reads differently in each format. · Arthur Wesley Dow · View of Ipswich, or A Bend in the River · ca. 1895 · The Met links this tiny upright print to Japanese pillar prints; its narrow frame stacks the view in bands, field to houses to river to hills."],[7,"/study/composition/arranging-a-picture/format.html","Composition · Example","View of Ipswich, or A Bend in the River","Arthur Wesley Dow","thumb/dow-view-of-ipswich","ca. 1895 · The Met links this tiny upright print to Japanese pillar prints; its narrow frame stacks the view in bands, field to houses to river to hills. · Format"],[7,"/study/composition/arranging-a-picture/positive-and-negative-space.html","Composition","Positive and Negative Space","","dow-notan-reversal","Positive space is the subject of a picture; negative space is everything around it. The edge of one is always the edge of the other, so both are designed together. · Félix Vallotton · Laziness (La Paresse) · 1896 · Vallotton uses no gray at all; the pale body is mostly bare paper, given its outline by the black around it."],[7,"/study/composition/arranging-a-picture/positive-and-negative-space.html","Composition · Example","Laziness (La Paresse)","Félix Vallotton","thumb/vallotton-laziness","1896 · Vallotton uses no gray at all; the pale body is mostly bare paper, given its outline by the black around it. · Positive and Negative Space"],[7,"/study/composition/arranging-a-picture/focal-point.html","Composition","Focal Point","","poore-lion-desert","The focal point is where the eye lands first. Painters build it with contrast, isolation, and placement, because the eye goes to whatever differs most from its surroundings. · Caravaggio · The Denial of Saint Peter · 1610 · Lit faces and hands stand out against near-black darkness, and the Met reads the pointing fingers as three accusations, matching Peter's three denials."],[7,"/study/composition/arranging-a-picture/focal-point.html","Composition · Example","The Denial of Saint Peter","Caravaggio","thumb/caravaggio-denial-of-saint-peter","1610 · Lit faces and hands stand out against near-black darkness, and the Met reads the pointing fingers as three accusations, matching Peter's three denials. · Focal Point"],[7,"/study/composition/arranging-a-picture/symmetric-balance.html","Composition","Symmetric Balance","","poore-salute-wounded","In symmetric balance the two sides of a center line carry about the same visual weight, often by mirroring each other, so the picture looks steady. Visual weight is the pull a shape has on the eye. · Raphael · Madonna and Child Enthroned with Saints (Colonna Altarpiece) · ca. 1504 · Raphael centers the Virgin and, in the arch above, God the Father, with a female and a male saint on each side, so the halves nearly mirror each other."],[7,"/study/composition/arranging-a-picture/symmetric-balance.html","Composition · Example","Madonna and Child Enthroned with Saints (Colonna Altarpiece)","Raphael","thumb/raphael-colonna-altarpiece","ca. 1504 · Raphael centers the Virgin and, in the arch above, God the Father, with a female and a male saint on each side, so the halves nearly mirror each other. · Symmetric Balance"],[7,"/study/composition/arranging-a-picture/asymmetric-balance.html","Composition","Asymmetric Balance","","poore-steelyard","Asymmetric balance pairs two unlike sides that still feel level. It works like a seesaw: a large shape near the center can be balanced by a small one far out toward the edge. · Mary Cassatt · Little Girl in a Blue Armchair · 1878 · Cassatt answers the large chair and sprawled girl right of center with a small dark dog and open floor at left, which keep the right from outweighing the left."],[7,"/study/composition/arranging-a-picture/asymmetric-balance.html","Composition · Example","Little Girl in a Blue Armchair","Mary Cassatt","thumb/cassatt-little-girl-in-a-blue-armchair","1878 · Cassatt answers the large chair and sprawled girl right of center with a small dark dog and open floor at left, which keep the right from outweighing the left. · Asymmetric Balance"],[7,"/study/composition/arranging-a-picture/armatures.html","Composition","Armatures","","poore-fundamental-forms","An armature is a simple figure, such as a triangle, circle, S-curve, cross, or L, that a picture's main shapes are built around, so many separate parts read as one arrangement. · Andrea del Sarto · The Holy Family with the Young Saint John the Baptist · ca. 1528 · The Met notes how the four figures' hands spiral around the globe John passes to the Christ Child, gathering the group around one point."],[7,"/study/composition/arranging-a-picture/armatures.html","Composition · Example","The Holy Family with the Young Saint John the Baptist","Andrea del Sarto","thumb/sarto-holy-family","ca. 1528 · The Met notes how the four figures' hands spiral around the globe John passes to the Christ Child, gathering the group around one point. · Armatures"],[7,"/study/composition/arranging-a-picture/thirds-and-the-golden-ratio.html","Composition","Thirds and the Golden Ratio","","poore-strong-points","The rule of thirds puts key things on lines cutting the frame in three each way; the golden ratio splits it about 62 to 38. Both treat some spots as stronger than others, on thin evidence. · Georges Seurat · Circus Sideshow (Parade de cirque) · 1887–88 · Seurat's stiff horizontals and verticals invite golden-ratio lines drawn over them, yet a study of his notes, sketches, and paintings, summarized in 1981, found no sign he used the ratio."],[7,"/study/composition/arranging-a-picture/thirds-and-the-golden-ratio.html","Composition · Example","Circus Sideshow (Parade de cirque)","Georges Seurat","thumb/seurat-circus-sideshow","1887–88 · Seurat's stiff horizontals and verticals invite golden-ratio lines drawn over them, yet a study of his notes, sketches, and paintings, summarized in 1981, found no sign he used the ratio. · Thirds and the Golden Ratio"],[7,"/study/composition/arranging-a-picture/leading-the-eye.html","Composition","Leading the Eye","","poore-shepherdess-exit","Painters plan a route for the eye: a way in, stops, and a way out. Bright spots, strong contrasts, and openings pull the eye, so their placement can lay out the route. · Johannes Vermeer · Young Woman with a Water Pitcher · ca. 1662 · Window light falls on the white headdress and collar, the pitcher, and the basin; a Met audio-guide speaker says it \"is guiding me around the room.\""],[7,"/study/composition/arranging-a-picture/leading-the-eye.html","Composition · Example","Young Woman with a Water Pitcher","Johannes Vermeer","thumb/vermeer-young-woman-with-a-water-pitcher","ca. 1662 · Window light falls on the white headdress and collar, the pitcher, and the basin; a Met audio-guide speaker says it \"is guiding me around the room.\" · Leading the Eye"],[7,"/study/composition/arranging-a-picture/depth.html","Composition","Depth","","dow-depth-hiroshige","Depth cues make a flat surface look deep by copying how things appear to the eye: a near object hides part of what is behind it (overlap), things look smaller with distance, and receding lines draw together (linear perspective). · Utagawa Hiroshige · Plum Estate, Kameido · 1857 · Hiroshige sets the plum trunk so close it runs off the frame and shows the orchard and its small visitors through its branches, with almost nothing in between: space jumps from very near to far."],[7,"/study/composition/arranging-a-picture/depth.html","Composition · Example","Plum Estate, Kameido","Utagawa Hiroshige","thumb/hiroshige-plum-estate-kameido","1857 · Hiroshige sets the plum trunk so close it runs off the frame and shows the orchard and its small visitors through its branches, with almost nothing in between: space jumps from very near to far. · Depth"],[8,"/study/art-history/early-renaissance.html","Early Renaissance in Italy · Overview","What to Look For","","masaccio-tribute-money","In Florence in the 1420s, painters began to make flat walls and panels look like real space, lit by a steady light. Over the next 60 years, painters across Italy worked out perspective and solid figures, learned to paint in oil, and painted stories from ancient myth. · Masaccio · The Tribute Money · about 1425–27"],[8,"/study/art-history/early-renaissance/italy-1425-1485/holy-trinity.html","Early Renaissance in Italy","Holy Trinity","Masaccio","masaccio-trinity","Masaccio · 1425–26 · Italian, 1401–1428 or 1429. Fresco, 262 1/2 × 124 3/4 in. Santa Maria Novella, Florence · The lines of the painted vault all run to one low point, near a standing viewer's eye level, so the flat wall seems to open into a deep chapel. The method is called linear perspective. · Counted among the first major paintings built on perspective. In 1570 it was hidden behind a stone altar; since 1952 it has been back on the stretch of church wall where it was first painted."],[8,"/study/art-history/early-renaissance/italy-1425-1485/the-baptism-of-christ.html","Early Renaissance in Italy","The Baptism of Christ","Piero della Francesca","piero-baptism","Piero della Francesca · probably about 1437–45 · Italian, about 1415/20–1492. Egg tempera on wood, 65 3/4 × 45 3/4 in. The National Gallery, London · Piero set the dove, the water bowl, and Christ's joined hands one above another on the center line and painted everything in pale, even light, so the scene looks perfectly still. · Made for a church in Sansepolcro, Piero's hometown, and called his earliest surviving work. The hills and town in the background are read as Sansepolcro and its valley."],[8,"/study/art-history/early-renaissance/italy-1425-1485/the-battle-of-san-romano.html","Early Renaissance in Italy","The Battle of San Romano","Paolo Uccello","uccello-san-romano","Paolo Uccello · probably about 1438–40 · Italian, about 1397–1475. Egg tempera with some oil on wood, 71 3/4 × 126 in. The National Gallery, London · Uccello laid the broken lances on the ground like lines on a grid, so the battlefield reads as a measured floor. · One of three battle panels made for the Florentine house of Leonardo Bartolini Salimbeni. The picture is much darker than when it was painted; among other changes, the silver leaf of the armor has tarnished."],[8,"/study/art-history/early-renaissance/italy-1425-1485/saint-jerome-in-his-study.html","Early Renaissance in Italy","Saint Jerome in his Study","Antonello da Messina","antonello-jerome","Antonello da Messina · about 1475 · Italian, active 1456, died 1479. Oil on wood, 18 × 14 1/4 in. The National Gallery, London · Antonello used oil paint to imitate textures, from rough stone to smooth tile, and to show daylight coming through several windows. · Painted in Venice. Antonello learned his handling of oil from Netherlandish painting, and an early viewer described this picture as a work by Jan van Eyck."],[8,"/study/art-history/early-renaissance/italy-1425-1485/primavera.html","Early Renaissance in Italy","Primavera","Sandro Botticelli","botticelli-primavera","Sandro Botticelli · about 1480 · Italian, 1445–1510. Tempera grassa on wood, 81 1/2 × 125 1/2 in. The Uffizi, Florence · Botticelli spread eight figures across a flowered lawn in a grove of orange trees, set Venus slightly back at the center, and put Cupid in the air above her. · First recorded in a Medici house in Florence, hanging above a chest with a back. At least 42 kinds of plants have been identified in the picture."],[8,"/study/art-history/early-renaissance/italy-1425-1485/lamentation-over-the-dead-christ.html","Early Renaissance in Italy","Lamentation over the Dead Christ","Andrea Mantegna","mantegna-dead-christ","Andrea Mantegna · about 1483 · Italian, 1431–1506. Tempera on canvas, 26 3/4 × 32 in. Pinacoteca di Brera, Milan · Mantegna foreshortened the body, drawing it shorter as it runs back from the feet, but evened out the sizes so the feet do not dwarf the head. · Probably made for the painter's own use; it is thought to be the picture found in his studio at his death."],[8,"/study/art-history/early-renaissance/italy-1425-1485/venus-and-mars.html","Early Renaissance in Italy","Venus and Mars","Sandro Botticelli","botticelli-venus-mars","Sandro Botticelli · about 1485 · Egg tempera and oil on wood, 27 1/4 × 68 1/4 in. The National Gallery, London · Botticelli stretched the two figures along a long, low panel, Venus awake at one end and Mars asleep at the other, and drew their bodies with clean outlines and light shading. · Probably ordered for a marriage, as a panel set into a bedchamber wall, at shoulder height or higher."],[9,"/study/art-history/fauvism-and-expressionism.html","Fauvism and Early Expressionism · Overview","What to Look For","","matisse-open-window-collioure","In 1905 a group of painters in Paris, soon nicknamed the Fauves, began using color for its own force rather than to describe things. Within a few years painters in Dresden, Munich, and Vienna pushed the same freedom further, into jagged line, raw paint, and, by 1913, pictures with almost no recognizable objects. · Henri Matisse · Open Window, Collioure · 1905"],[9,"/study/art-history/fauvism-and-expressionism/paris-dresden-munich-and-vienna-1905-1915/woman-with-a-hat.html","Fauvism and Early Expressionism","Woman with a Hat","Henri Matisse","matisse-woman-with-a-hat","Henri Matisse · 1905 · French, 1869–1954. Oil on canvas, 31 3/4 × 23 1/2 in. San Francisco Museum of Modern Art · Matisse built the face from patches of green, mauve, yellow, and orange, with only a few touches the color of skin. Green runs down the nose and jawline where shadow would fall, so the face has shape without brown or gray. · Shown at the Salon d'Automne in Paris in 1905, where a critic called Matisse and his colleagues “les fauves,” the wild beasts. The sitter is the artist's wife, Amélie."],[9,"/study/art-history/fauvism-and-expressionism/paris-dresden-munich-and-vienna-1905-1915/mountains-at-collioure.html","Fauvism and Early Expressionism","Mountains at Collioure","André Derain","derain-mountains-at-collioure","André Derain · 1905 · French, 1880–1954. Oil on canvas, 32 × 39 1/2 in. National Gallery of Art, Washington · Derain made the trees from separate dashes of pure blue, green, and yellow, with pale ground showing between them. Even the darkest dashes are deep blue and blue-green, not black or brown, so the shaded foliage stays strongly colored. · Derain and Matisse worked side by side at Collioure in summer 1905."],[9,"/study/art-history/fauvism-and-expressionism/paris-dresden-munich-and-vienna-1905-1915/street-dresden.html","Fauvism and Early Expressionism","Street, Dresden","Ernst Ludwig Kirchner","kirchner-street-dresden","Ernst Ludwig Kirchner · 1908, reworked 1919 · German, 1880–1938. Oil on canvas, 59 1/4 × 79 in. The Museum of Modern Art, New York · Kirchner painted the street acid pink and gave the crowd pressing at the front edge green and orange faces. The pink pavement climbs the canvas without getting paler, so the street seems to stand up behind the crowd. · Kirchner helped found Die Brücke (The Bridge), a group of German painters, in Dresden in 1905; the street is the Königstrasse, and the canvas carries a date of 1907, a year before it was painted."],[9,"/study/art-history/fauvism-and-expressionism/paris-dresden-munich-and-vienna-1905-1915/blue-horse-i.html","Fauvism and Early Expressionism","Blue Horse I","Franz Marc","marc-blue-horse-i","Franz Marc · 1911 · German, 1880–1916. Oil on canvas, 44 × 33 1/4 in. Städtische Galerie im Lenbachhaus, Munich · Marc painted the horse blue from mane to hoof and set it in equally unreal hills of red, yellow, and green. The hills are curved bands that repeat the curves of the horse's neck and back, so horse and land tie together. · Marc wrote to his friend the painter August Macke in December 1910 that blue stood for the male principle, yellow for the female, and red for matter."],[9,"/study/art-history/fauvism-and-expressionism/paris-dresden-munich-and-vienna-1905-1915/composition-vii.html","Fauvism and Early Expressionism","Composition VII","Wassily Kandinsky","kandinsky-composition-vii","Wassily Kandinsky · 1913 · Russian, 1866–1944. Oil on canvas, about 79 × 118 in. State Tretyakov Gallery, Moscow · Kandinsky filled the canvas with color patches and black lines that pull toward the center, and left almost no object recognizable. The thickest black lines knot just left of center, crossing the colors without enclosing them. · Painted in four days, November 25 to 28, 1913, after more than thirty studies."],[9,"/study/art-history/fauvism-and-expressionism/paris-dresden-munich-and-vienna-1905-1915/self-portrait-laughing.html","Fauvism and Early Expressionism","Self-Portrait, Laughing","Richard Gerstl","gerstl-laughing-self-portrait","Richard Gerstl · 1908 · Austrian, 1883–1908. Oil on canvas, 15 3/4 × 12 in. Belvedere, Vienna · Gerstl smeared and dabbed the paint so thickly that the right edge of the face blurs into the brown dabs behind it. The background's browns and ochres are close to the skin's, so the head stands apart mainly by being lighter. · Gerstl kept apart from Vienna's artist groups and died at twenty-five."],[9,"/study/art-history/fauvism-and-expressionism/paris-dresden-munich-and-vienna-1905-1915/death-and-maiden.html","Fauvism and Early Expressionism","Death and Maiden","Egon Schiele","schiele-death-and-maiden","Egon Schiele · 1915 · Austrian, 1890–1918. Oil on canvas, 59 × 70 3/4 in. Belvedere, Vienna · Schiele broke the sheet and ground into jagged, crumpled shapes and painted the robe a darker shade of the ground's browns. Each sharp fold of the white sheet is edged with a dark line, so it reads as a broken surface, not soft cloth. · The man is Schiele himself and the woman holding on to him is Wally Neuzil, whom he left to marry Edith Harms."],[10,"/study/art-history/high-renaissance.html","High Renaissance · Overview","What to Look For","","perugino-keys","High Renaissance is the name for Italian painting of the early 1500s, made mainly in Florence, Rome, and Venice. Perugino, Raphael's teacher, painted this fresco in the Sistine Chapel a generation before the works that follow. · Pietro Perugino · Christ Giving the Keys to Saint Peter · 1481–82"],[10,"/study/art-history/high-renaissance/italy-1481-1518/the-last-supper.html","High Renaissance","The Last Supper","Leonardo da Vinci","leonardo-last-supper","Leonardo da Vinci · about 1494–98 · Italian, 1452–1519. Tempera and oil on plaster, about 181 × 346 1/2 in. Refectory of Santa Maria delle Grazie, Milan · This painting began a new era in art. The receding lines of the painted room run toward Christ's head, so the architecture itself points at him. · Leonardo painted on dry plaster instead of wet, which let him work slowly and change what he had done. The paint began to flake within a few years; a restoration finished in 1999 removed later repainting."],[10,"/study/art-history/high-renaissance/italy-1481-1518/mona-lisa.html","High Renaissance","Mona Lisa","Leonardo da Vinci","leonardo-mona-lisa","Leonardo da Vinci · 1503–19 · Oil on poplar panel, 31 1/4 × 21 in. Musée du Louvre, Paris · The edges of the face fade into shadow with no drawn line, a method called sfumato. Painters of the time, the young Raphael among them, drew on this portrait for their own. · Leonardo began it by October 1503 and had not finished it when he died. Old, yellowed varnish now turns the blue of the sky toward green and darkens the lower part."],[10,"/study/art-history/high-renaissance/italy-1481-1518/holy-family-doni-tondo.html","High Renaissance","Holy Family (Doni Tondo)","Michelangelo","michelangelo-doni","Michelangelo · 1505–6 · Italian, 1475–1564. Tempera grassa (tempera with added oil) on wood, 47 1/4 in. across. The Uffizi, Florence · The hard, bright folds of cloth make the figures look carved from stone. · Made for the Florentine merchant Agnolo Doni, who married Maddalena Strozzi in 1504. No other panel painting is certainly by Michelangelo."],[10,"/study/art-history/high-renaissance/italy-1481-1518/the-school-of-athens.html","High Renaissance","The School of Athens","Raphael","raphael-school-of-athens","Raphael · about 1509–11 · Italian, 1483–1520. Fresco, about 196 3/4 × 303 1/4 in. Stanza della Segnatura, Vatican · The Vatican Museums date the start of the High Renaissance to the frescoes in this room. The arches shrink, one inside the next, toward two men at the center. · Painted for Pope Julius II in a room he used as his library. The painted hall was inspired by Bramante's design for rebuilding St. Peter's. Raphael's cartoon for the figures survives in Milan."],[10,"/study/art-history/high-renaissance/italy-1481-1518/the-libyan-sibyl.html","High Renaissance","The Libyan Sibyl","Michelangelo","michelangelo-libyan-sibyl","Michelangelo · about 1511–12 · Fresco, about 178 3/4 × 149 1/2 in. (her section of the ceiling). Sistine Chapel ceiling, Vatican · The shoulders turn away while the knees face front, so the seated figure looks caught in the middle of a turn. Michelangelo's color in the second half of the ceiling influenced many of the painters later called Mannerists. · Michelangelo painted her in about twenty daily sections of plaster. A red chalk study for the pose, drawn from a male model, is in the Metropolitan Museum of Art, New York."],[10,"/study/art-history/high-renaissance/italy-1481-1518/the-sistine-madonna.html","High Renaissance","The Sistine Madonna","Raphael","raphael-sistine-madonna","Raphael · 1512–13 · Oil on canvas, 106 × 79 1/4 in. Gemäldegalerie Alte Meister, Dresden · Curtains drawn back at the top and a ledge at the bottom make the scene look like a vision. Since about 1800, the two small angels on the ledge have been copied on their own. · Raphael made it for the high altar of the convent church of San Sisto in Piacenza, most likely on the order of Pope Julius II. Raphael added the two angels last."],[10,"/study/art-history/high-renaissance/italy-1481-1518/assumption-of-the-virgin.html","High Renaissance","Assumption of the Virgin","Titian","titian-assumption","Titian · 1516–18 · Italian, about 1488/90–1576. Oil on panel, 263 × 135 1/2 in. Santa Maria Gloriosa dei Frari, Venice · Raised arms link its three tiers of figures, so the eye climbs from the apostles on the ground to the top. · Unveiled on the high altar of the Frari, a Franciscan church, on May 19, 1518. The figure of God, far above the viewer, is painted boldly with thick, unblended highlights."],[11,"/study/art-history/impressionism.html","Impressionism · Overview","What to Look For","","pissarro-hoarfrost","Impressionism took shape in and around Paris from the late 1860s, and its painters first showed together in 1874, in an exhibition they organized themselves. They worked in short, separate strokes of bright, unblended color and often painted shadows in color, and conservative critics called the results unfinished. · Camille Pissarro · Hoarfrost · 1873"],[11,"/study/art-history/impressionism/paris-1872-1894/impression-sunrise.html","Impressionism","Impression, Sunrise","Claude Monet","monet-impression","Claude Monet · 1872 · French, 1840–1926. Oil on canvas, 19 3/4 × 25 1/2 in. Musée Marmottan Monet, Paris · Monet painted the harbor in a few hours, in paint thin enough to let the weave of the canvas show. The orange sun and its broken reflection went on last, thick over thin blue-gray, so they stand out as the strongest color. · Shown at the first Impressionist exhibition, in Paris in 1874. The critic Louis Leroy used its title to mock the picture as a mere sketch, and the name stuck to the group."],[11,"/study/art-history/impressionism/paris-1872-1894/the-cradle.html","Impressionism","The Cradle","Berthe Morisot","morisot-cradle","Berthe Morisot · 1872 · French, 1841–1895. Oil on canvas, 22 × 18 1/4 in. Musée d'Orsay, Paris · Morisot painted the veil over the cradle in thin strokes of white that let the baby show through. Beneath it the mother's dark sleeve turns gray, so the cloth looks sheer. · Hung in the 1874 exhibition, where Morisot was the first woman to show with the group. The sitter is her sister Edma, watching her daughter Blanche."],[11,"/study/art-history/impressionism/paris-1872-1894/the-dance-class.html","Impressionism","The Dance Class","Edgar Degas","degas-dance-class","Edgar Degas · 1874 · French, 1834–1917. Oil on canvas, 32 3/4 × 30 1/2 in. The Metropolitan Museum of Art, New York · Degas left the middle of the floor empty and pushed the dancers to the edges, where the frame cuts some off. The dancers shrink fast from the lower left to the far corner, so the room looks deep. · Shown at the second Impressionist exhibition, 1876; the teacher is the ballet master Jules Perrot."],[11,"/study/art-history/impressionism/paris-1872-1894/bal-du-moulin-de-la-galette.html","Impressionism","Bal du moulin de la Galette","Pierre-Auguste Renoir","renoir-galette","Pierre-Auguste Renoir · 1876 · French, 1841–1919. Oil on canvas, 51 3/4 × 69 1/2 in. Musée d'Orsay, Paris · Renoir painted sunlight through leaves as loose, pale patches laid across the dancers. Strokes of blue, pink, and yellow repeat across the whole crowd, tying it together. · Shown at the third Impressionist exhibition, 1877, where critics objected to the blurred forms. Some of Renoir's friends posed for it."],[11,"/study/art-history/impressionism/paris-1872-1894/paris-street-rainy-day.html","Impressionism","Paris Street; Rainy Day","Gustave Caillebotte","caillebotte-rainy-day","Gustave Caillebotte · 1877 · French, 1848–1894. Oil on canvas, 83 1/2 × 108 3/4 in. The Art Institute of Chicago · Caillebotte applied the smooth finish and measured perspective of the art schools to a modern street with cropped figures. With almost no brushstroke showing, the wet paving stones and umbrellas read as shiny, solid surfaces. · It dominated the 1877 exhibition, which Caillebotte largely organized."],[11,"/study/art-history/impressionism/paris-1872-1894/little-girl-in-a-blue-armchair.html","Impressionism","Little Girl in a Blue Armchair","Mary Cassatt","cassatt-blue-armchair","Mary Cassatt · 1878 · American, 1844–1926. Oil on canvas, 35 1/4 × 51 in. National Gallery of Art, Washington · Cassatt built the room from a few large blue shapes, with the gray-brown floor left plain between them. Loose red, green, and white strokes dot every chair but stop at the floor. · Cassatt wrote that Degas helped with it; he probably painted part of the background."],[11,"/study/art-history/impressionism/paris-1872-1894/rouen-cathedral-west-facade-sunlight.html","Impressionism","Rouen Cathedral, West Façade, Sunlight","Claude Monet","monet-rouen-sunlight","Claude Monet · 1894 · Oil on canvas, 39 1/2 × 26 in. National Gallery of Art, Washington · Monet built the cathedral front from thick, crusted paint, as rough as the stone it depicts. Doorways and towers break into patches of white, yellow, blue, and pink, so the façade looks sunlit but no single carving is clear. · One of more than thirty views painted in 1892 and 1893 from rooms facing the cathedral. Monet moved between canvases as the light changed and finished them at Giverny in 1894."],[12,"/study/art-history/japanese-woodblock-prints.html","Japanese Woodblock Prints · Overview","What to Look For","","hokusai-red-fuji","Ukiyo-e, “pictures of the floating world,” were woodblock prints sold in Edo, the city now called Tokyo, from the 1680s into the 1880s. Each print took four people: a designer, a block carver, a printer, and the publisher who sold it. · Katsushika Hokusai · South Wind, Clear Sky (Red Fuji) · about 1830–32"],[12,"/study/art-history/japanese-woodblock-prints/japan-1680s-1880s/the-entrance-to-ageya-machi.html","Japanese Woodblock Prints","The Entrance to Ageya-machi","Hishikawa Moronobu","moronobu-entrance-ageya-machi","Hishikawa Moronobu · 1681–84 · Japanese, 1618–1694. Woodblock print; ink on paper, 10 × 15 1/4 in. The Metropolitan Museum of Art, New York · Moronobu designed everything for black ink alone, with no color and no shading. · A samurai and his servant have just come through the gate of the Yoshiwara, the pleasure quarter of Edo."],[12,"/study/art-history/japanese-woodblock-prints/japan-1680s-1880s/woman-admiring-plum-blossoms-at-night.html","Japanese Woodblock Prints","Woman Admiring Plum Blossoms at Night","Suzuki Harunobu","harunobu-plum-blossoms-night","Suzuki Harunobu · about 1766 · Japanese, 1725–1770. Woodblock print with embossing; ink and color on paper, 12 3/4 × 8 1/4 in. The Metropolitan Museum of Art, New York · Harunobu covered about half the sheet in a solid black night and set flat color against it. · Full-color printing, with every color printed from its own carved block, began in Edo in 1765. The socks and inner robes are embossed: pressed into the paper without ink."],[12,"/study/art-history/japanese-woodblock-prints/japan-1680s-1880s/three-beauties-of-the-kansei-period.html","Japanese Woodblock Prints","Three Beauties of the Kansei Period","Kitagawa Utamaro","utamaro-three-beauties-kansei","Kitagawa Utamaro · about 1791 · Japanese, about 1754–1806. Woodblock print; ink and color on paper, 15 1/4 × 10 in. The Metropolitan Museum of Art, New York · Utamaro filled the sheet with three heads and shoulders, seen close up, and left the faces as bare paper. · A close-up bust portrait is called an ōkubi-e, a “big-head picture.”"],[12,"/study/art-history/japanese-woodblock-prints/japan-1680s-1880s/otani-oniji-iii-as-yakko-edobei.html","Japanese Woodblock Prints","Ōtani Oniji III as Yakko Edobei","Tōshūsai Sharaku","sharaku-otani-oniji","Tōshūsai Sharaku · 1794 · Japanese, active 1794–95. Woodblock print; ink, color, and white mica on paper, 15 × 10 in. The Metropolitan Museum of Art, New York · Sharaku pushed the face and hands toward caricature and set them against a dark, flat ground. · A kabuki actor plays a ruthless manservant. The mica in the print is a mineral powder."],[12,"/study/art-history/japanese-woodblock-prints/japan-1680s-1880s/under-the-wave-off-kanagawa-the-great-wave.html","Japanese Woodblock Prints","Under the Wave off Kanagawa (The Great Wave)","Katsushika Hokusai","hokusai-great-wave","Katsushika Hokusai · about 1830–32 · Japanese, 1760–1849. Woodblock print; ink and color on paper, 10 × 15 in. The Metropolitan Museum of Art, New York · Hokusai set a huge near wave against a tiny far mountain and printed the wave in three blues. · From the series Thirty-six Views of Mount Fuji. The artist was known for landscapes printed with indigo and Prussian blue, an imported pigment."],[12,"/study/art-history/japanese-woodblock-prints/japan-1680s-1880s/plum-garden-at-kameido.html","Japanese Woodblock Prints","Plum Garden at Kameido","Utagawa Hiroshige","hiroshige-kameido-plum","Utagawa Hiroshige · 1857 · Japanese, 1797–1858. Color woodblock print, 14 1/4 × 9 1/2 in. The Art Institute of Chicago · Hiroshige pushed a dark tree trunk right up against the viewer and let the edges of the sheet crop it. · From One Hundred Famous Views of Edo. Vincent van Gogh painted a copy of the design in 1887."],[12,"/study/art-history/japanese-woodblock-prints/japan-1680s-1880s/moon-over-daimotsu-bay-benkei.html","Japanese Woodblock Prints","Moon over Daimotsu Bay: Benkei","Tsukioka Yoshitoshi","yoshitoshi-benkei-moon","Tsukioka Yoshitoshi · 1886 · Japanese, 1839–1892. Woodblock print; ink and color on paper, 13 3/4 × 9 3/4 in. Minneapolis Institute of Art · Yoshitoshi curled a tall black wave up the left side and kept almost the whole sheet to black and gray. · In a storm, the warrior-monk Benkei prays to stop the ghosts of slain enemies from rising and drowning him and his companions. From the series One Hundred Aspects of the Moon."],[13,"/study/art-history/japonisme.html","Japonisme · Overview","What to Look For","","monet-la-japonaise","Japonisme is the French name for the craze for Japanese art and design that spread through France, the rest of Europe, and North America after Japan reopened trade with the West in the 1850s. Some artists painted fans, robes, and prints as studio props; others borrowed what Japanese woodblock prints did with form: flat, bright color, firm outlines, views from above, and figures cut off by the edge. · Claude Monet · La Japonaise (Camille Monet in Japanese Costume) · 1876"],[13,"/study/art-history/japonisme/europe-and-the-united-states-1864-1895/caprice-in-purple-and-gold-the-golden-screen.html","Japonisme","Caprice in Purple and Gold: The Golden Screen","James McNeill Whistler","whistler-golden-screen","James McNeill Whistler · 1864 · American, 1834–1903. Oil on wood panel, 19 3/4 × 27 in. Freer Gallery of Art, Smithsonian, Washington · Whistler used Japanese objects as studio props: a gold folding screen, purple and red robes, and prints scattered on the floor. The loosely brushed buildings sit on flat gold, so the screen reads as a flat painted object, not an outdoor view. · The model, Joanna Hiffernan, studies a print from Hiroshige's series Views of the Sixty-odd Provinces."],[13,"/study/art-history/japonisme/europe-and-the-united-states-1864-1895/soup-plate-rousseau-service.html","Japonisme","Soup Plate, Rousseau Service","Félix Bracquemond","bracquemond-rousseau-plate","Félix Bracquemond · 1866–75 · French, 1833–1914. Creamware, diameter 9 3/4 in. The Metropolitan Museum of Art, New York · Bracquemond scattered a few motifs off-center on the white plate and drew each in dark outline. Wide white space around each one makes the turkey, moth, and sprig read as separate drawings. · Bracquemond owned Hokusai's Manga, a many-volume book of sketches, earlier than most Europeans, and his designs for the service draw on it."],[13,"/study/art-history/japonisme/europe-and-the-united-states-1864-1895/flowering-plum-orchard-after-hiroshige.html","Japonisme","Flowering Plum Orchard (after Hiroshige)","Vincent van Gogh","vangogh-flowering-plum-orchard","Vincent van Gogh · 1887 · Dutch, 1853–1890. Oil on canvas, 22 × 18 1/2 in. Van Gogh Museum, Amsterdam · Van Gogh copied a Japanese print in oil paint and made its colors stronger, especially the red sky and green grass. He added orange borders with large dark green characters, so strong color runs to the edge of the canvas. · The first of three paintings he made after prints in his own collection, here Hiroshige's Plum Garden in Kameido."],[13,"/study/art-history/japonisme/europe-and-the-united-states-1864-1895/the-letter.html","Japonisme","The Letter","Mary Cassatt","cassatt-letter","Mary Cassatt · 1890–91 · American, 1844–1926. Color aquatint and drypoint, plate 13 3/4 × 8 1/4 in. Art Institute of Chicago · Cassatt covered the dress and the wallpaper in pattern and kept the color in flat areas. The face and hands are plain pale shapes with fine dark outlines, which makes the dress and wallpaper look busier. · One of ten color prints she made after seeing an exhibition of Japanese prints in Paris in spring 1890."],[13,"/study/art-history/japonisme/europe-and-the-united-states-1864-1895/moulin-rouge-la-goulue.html","Japonisme","Moulin Rouge: La Goulue","Henri de Toulouse-Lautrec","lautrec-la-goulue","Henri de Toulouse-Lautrec · 1891 · French, 1864–1901. Color lithograph, three sheets joined, 74 3/4 × 46 in. The Metropolitan Museum of Art, New York · Toulouse-Lautrec built the poster from flat shapes and bold lettering, with yellow lamps above the dance floor. The crowd is one solid black shape with no faces, so the dancer's white petticoats stand out against it. · His first poster, made to advertise the Moulin Rouge dance hall in Paris."],[13,"/study/art-history/japonisme/europe-and-the-united-states-1864-1895/the-protest.html","Japonisme","The Protest","Félix Vallotton","vallotton-protest","Félix Vallotton · 1893 · Swiss French, 1865–1925. Woodcut, image 8 × 12 1/2 in. The Cleveland Museum of Art · Vallotton set solid black figures racing across bare paper, seen from above. The empty lower-right corner makes the crowd look packed into the top of the sheet. · Police are breaking up a political demonstration."],[13,"/study/art-history/japonisme/europe-and-the-united-states-1864-1895/boats-at-rest.html","Japonisme","Boats at Rest","Arthur Wesley Dow","dow-boats-at-rest","Arthur Wesley Dow · about 1895 · American, 1857–1922. Oil on canvas, 26 × 36 in. Art Institute of Chicago · Dow showed the rowboats from above and let the left edge cut off a shed. The river curves up toward a high horizon, so the ground seems to tilt and the boats' insides are in full view. · Through his books and teaching, Dow's ideas on composition shaped many Arts and Crafts designers."],[14,"/study/art-history/mannerism.html","Mannerism · Overview","What to Look For","","bronzino-eleonora","Mannerism took hold in Italy about 1520, between the High Renaissance and the Baroque, lasted there until about 1600, and spread across much of Europe. Painters stretched and twisted the body, flattened the space, and traded calm balance for tension and elegance. · Agnolo Bronzino · Portrait of Eleonora di Toledo with Her Son Giovanni · about 1545"],[14,"/study/art-history/mannerism/italy-and-spain-1518-1588/joseph-with-jacob-in-egypt.html","Mannerism","Joseph with Jacob in Egypt","Jacopo Pontormo","pontormo-joseph-egypt","Jacopo Pontormo · probably 1518 · Italian, 1494–1557. Oil on wood, 38 × 43 in. The National Gallery, London · Four moments of the story are scattered across one picture, with figures at very different sizes and no clear center. The bright, acid colors show the pull of Michelangelo's Sistine ceiling. · One of a set of panels made for the bedroom of the Florentine banker Pierfrancesco Borgherini, who married in 1515. Vasari named the boy with a basket on the bottom step as Pontormo's apprentice, Bronzino."],[14,"/study/art-history/mannerism/italy-and-spain-1518-1588/deposition.html","Mannerism","Deposition","Jacopo Pontormo","pontormo-deposition","Jacopo Pontormo · 1525–28 · Paint on wood panel, 123 1/4 × 75 1/2 in. Capponi Chapel, Santa Felicita, Florence · Most of the colors are mixed with white, so the pinks, blues, and greens look pale and the bodies seem to weigh little. There is no cross and no landscape, only a single cloud. · Made for the banker Ludovico Capponi's family chapel, where it still hangs. Pontormo let no one, not even Capponi, see it until it was unveiled."],[14,"/study/art-history/mannerism/italy-and-spain-1518-1588/self-portrait-in-a-convex-mirror.html","Mannerism","Self-Portrait in a Convex Mirror","Parmigianino","parmigianino-self-portrait","Parmigianino · about 1523–24 · Italian, 1503–1540. Paint on a curved poplar panel, 9 1/2 in. across. Kunsthistorisches Museum, Vienna · It copies what a convex mirror shows: the hand in front swells, and the window and ceiling bend around the face. · After arriving in Rome, the young painter gave it to Pope Clement VII to win him as a patron. It later belonged to the writer Pietro Aretino."],[14,"/study/art-history/mannerism/italy-and-spain-1518-1588/madonna-with-the-long-neck.html","Mannerism","Madonna with the Long Neck","Parmigianino","parmigianino-long-neck","Parmigianino · 1534–40 · Oil on panel, 85 1/4 × 52 1/4 in. The Uffizi, Florence · Mary's neck, fingers, and body are drawn out far past life, and the tall white column beside her repeats the length of her neck. · Commissioned in 1534 for a church in Parma, it was still unfinished in Parmigianino's studio when he died in 1540. The Latin line at the column's base, added two years later, says fate kept him from completing it."],[14,"/study/art-history/mannerism/italy-and-spain-1518-1588/an-allegory-with-venus-and-cupid.html","Mannerism","An Allegory with Venus and Cupid","Agnolo Bronzino","bronzino-allegory","Agnolo Bronzino · about 1545 · Italian, 1503–1572. Oil on wood, 57 1/2 × 45 3/4 in. The National Gallery, London · The brushstrokes are blended away, so the bodies look smooth and hard as polished marble against the ultramarine blue. The figures fill the frame with almost no space behind them. · It is probably the painting Vasari describes as sent to King Francis I of France, most likely a gift from Cosimo I de' Medici, who employed Bronzino as his court painter."],[14,"/study/art-history/mannerism/italy-and-spain-1518-1588/the-origin-of-the-milky-way.html","Mannerism","The Origin of the Milky Way","Jacopo Tintoretto","tintoretto-milky-way","Jacopo Tintoretto · about 1575 · Italian, about 1518–1594. Oil on canvas, 58 3/4 × 66 1/4 in. The National Gallery, London · Jupiter dives in from the upper right to set his infant son Hercules at the breast of the sleeping Juno; her spilled milk became the Milky Way. Every body tilts or tumbles, and none stands upright. · Some time before 1727, roughly the lower third of the canvas was cut away. An old, smaller copy shows the missing part."],[14,"/study/art-history/mannerism/italy-and-spain-1518-1588/the-burial-of-the-count-of-orgaz.html","Mannerism","The Burial of the Count of Orgaz","El Greco","el-greco-orgaz","El Greco · 1586–88 · Greek, 1541–1614. Oil on canvas, 189 × 141 3/4 in. Santo Tomé, Toledo · The picture splits in two: below, a solid row of mourners in black; above, long, angular figures painted more loosely, in a zone of cooler silvers and lilacs. · Made for the chapel in El Greco's own parish church where Gonzalo Ruiz, lord of Orgaz, is buried, and still there. The contract asked for the town's leading men to be shown as mourners; the boy at lower left is El Greco's son."],[15,"/study/art-history/neoclassicism.html","Neoclassicism · Overview","What to Look For","","david-socrates","Neoclassicism turned back to ancient Greece and Rome for clear outlines, calm order, and serious subjects of duty and sacrifice. It began with painters working in Rome in the 1760s, spread to London, and reached its height in Paris around the French Revolution. · Jacques-Louis David · The Death of Socrates · 1787"],[15,"/study/art-history/neoclassicism/rome-paris-and-london-1763-1800/the-death-of-lucretia.html","Neoclassicism","The Death of Lucretia","Gavin Hamilton","hamilton-lucretia","Gavin Hamilton · 1763–67 · Scottish, 1723–1798. Oil on canvas, 84 × 104 in. Yale Center for British Art, New Haven · Hamilton lined the figures up across the front like a carved relief and gave them big, readable gestures. A dark curtain closes off the space behind them, so nothing opens up beyond. · Roman men swearing revenge over the body of Lucretia, painted in Rome about twenty years before David's Oath of the Horatii."],[15,"/study/art-history/neoclassicism/rome-paris-and-london-1763-1800/the-death-of-general-wolfe.html","Neoclassicism","The Death of General Wolfe","Benjamin West","west-death-of-wolfe","Benjamin West · 1770 · American, 1738–1820. Oil on canvas, 60 × 84 1/2 in. National Gallery of Canada, Ottawa · West arranged a modern death as a mourning group around a fallen hero, in contemporary uniforms rather than togas. Officers lean in from both sides under the flag, so a lit triangle leads the eye down to the dying general. · A general dying at the Battle of Quebec in 1759; shown at the Royal Academy in London in 1771."],[15,"/study/art-history/neoclassicism/rome-paris-and-london-1763-1800/cornelia-mother-of-the-gracchi-pointing-to-her-children-as-her-treasures.html","Neoclassicism","Cornelia, Mother of the Gracchi, Pointing to Her Children as Her Treasures","Angelica Kauffman","kauffman-cornelia","Angelica Kauffman · about 1785 · Swiss, 1741–1807. Oil on canvas, 40 × 50 in. Virginia Museum of Fine Arts, Richmond · Kauffman kept the color calm and even and stood the figures before plain columns. Each color keeps to its own area and nothing sits in deep shadow, so the whole row of figures looks still. · A visitor shows off her jewelry, and the Roman mother answers by pointing to her sons as her treasures."],[15,"/study/art-history/neoclassicism/rome-paris-and-london-1763-1800/the-oath-of-the-horatii.html","Neoclassicism","The Oath of the Horatii","Jacques-Louis David","david-horatii","Jacques-Louis David · 1784–85 · French, 1748–1825. Oil on canvas, 130 × 167 1/4 in. Musée du Louvre, Paris · David drew hard outlines and straight limbs and set the figures in a space no deeper than a stage. The men are all sharp angles, the women soft, sinking curves. · Three Roman brothers swear to fight for their city; shown at the Paris Salon of 1785."],[15,"/study/art-history/neoclassicism/rome-paris-and-london-1763-1800/self-portrait-with-two-pupils.html","Neoclassicism","Self-Portrait with Two Pupils","Adélaïde Labille-Guiard","labille-guiard-pupils","Adélaïde Labille-Guiard · 1785 · French, 1749–1803. Oil on canvas, 83 × 59 1/2 in. The Metropolitan Museum of Art, New York · Labille-Guiard painted satin, lace, straw, and skin each at full sharpness. Crisp, near-white highlights make the silver-blue silk read as stiff, shiny satin. · A painter at her easel with her two students, shown at the Salon of 1785."],[15,"/study/art-history/neoclassicism/rome-paris-and-london-1763-1800/the-death-of-marat.html","Neoclassicism","The Death of Marat","Jacques-Louis David","david-marat","Jacques-Louis David · 1793 · Oil on canvas, 65 × 50 1/2 in. Royal Museums of Fine Arts of Belgium, Brussels · David left the upper half as bare, brushed brown wall and set everything else in a band across the bottom. The few colors, white sheet, green cloth, and yellow wood, all sit in that band, so the wall above looks even emptier. · A murdered revolutionary journalist; the crate carries the painter's dedication, dated to year two of the Republic."],[15,"/study/art-history/neoclassicism/rome-paris-and-london-1763-1800/napoleon-crossing-the-alps.html","Neoclassicism","Napoleon Crossing the Alps","Jacques-Louis David","david-napoleon-alps","Jacques-Louis David · 1800 · Oil on canvas, 102 × 87 in. Musée national du château de Malmaison, Rueil-Malmaison · David built the picture on one strong diagonal, from the horse's hind legs at lower right to the cloak at upper left, so horse and rider seem to climb. · The First Consul crossing the Alps in 1800; the rocks below carry the names of Bonaparte, Hannibal, and Charlemagne."],[16,"/study/art-history/northern-renaissance.html","Northern Renaissance · Overview","What to Look For","","campin-merode","In the 1400s, painters in the Low Countries used oil paint, laid on in thin layers, to show everyday rooms, cloth, and light in close detail. By the late 1400s the new style had reached Germany, helped by printed pictures that traveled widely. · Workshop of Robert Campin · Annunciation Triptych (Merode Altarpiece) · about 1427–32"],[16,"/study/art-history/northern-renaissance/northern-europe-1434-1565/the-arnolfini-portrait.html","Northern Renaissance","The Arnolfini Portrait","Jan van Eyck","eyck-arnolfini","Jan van Eyck · 1434 · Netherlandish, active 1422, died 1441. Oil on oak, 32 1/4 × 23 1/2 in. National Gallery, London · A round mirror at the center of the back wall repeats the room in miniature, seen from the other side. · Van Eyck signed the wall above the mirror in Latin: \"Jan van Eyck was here, 1434.\" The mirror's reflection includes two people coming in at a door."],[16,"/study/art-history/northern-renaissance/northern-europe-1434-1565/the-descent-from-the-cross.html","Northern Renaissance","The Descent from the Cross","Rogier van der Weyden","weyden-descent","Rogier van der Weyden · before 1443 · Netherlandish, about 1399–1464. Oil on panel, 80 1/2 × 103 in. Museo del Prado, Madrid · Ten nearly life-size figures crowd a gilded box whose space does not match the room they need. · Apparently painted for the chapel of the crossbowmen's guild in Leuven; two small crossbows hang in the painted corners. A copy dated 1443 gives the latest possible date."],[16,"/study/art-history/northern-renaissance/northern-europe-1434-1565/the-garden-of-earthly-delights-triptych.html","Northern Renaissance","The Garden of Earthly Delights Triptych","Hieronymus Bosch","bosch-garden","Hieronymus Bosch · 1490–1500 · Netherlandish, about 1450–1516. Oil on oak; 73 1/4 in. high, center panel 68 in. wide, wings 30 in. wide. Museo del Prado, Madrid · One landscape with a high horizon crosses all three panels, and crowds of small figures are stacked up the surface in bands. · First recorded in 1517 in the Nassau palace in Brussels. Technical study shows Bosch first planned a different scene, the creation of Eve, for the left panel."],[16,"/study/art-history/northern-renaissance/northern-europe-1434-1565/self-portrait-with-fur-trimmed-robe.html","Northern Renaissance","Self-Portrait with Fur-Trimmed Robe","Albrecht Dürer","durer-self-1500","Albrecht Dürer · 1500 · German, 1471–1528. Paint on limewood panel, 26 1/2 × 19 1/4 in. Alte Pinakothek, Munich · The head faces straight out with both halves of the face matched, a pose then used for images of Christ. · The Latin inscription at right gives his name, his city, Nuremberg, and his age, twenty-eight."],[16,"/study/art-history/northern-renaissance/northern-europe-1434-1565/adam-and-eve.html","Northern Renaissance","Adam and Eve","Albrecht Dürer","durer-adam-eve","Albrecht Dürer · 1504 · Engraving, 9 7/8 × 7 7/8 in. The Metropolitan Museum of Art, New York · An engraving is cut into a metal plate, and fine lines packed close together give form, texture, and shading at once. · The poses follow a system of ideal proportion that Dürer studied all his life. Adam recalls an ancient statue of Apollo dug up in the late 1400s."],[16,"/study/art-history/northern-renaissance/northern-europe-1434-1565/the-ambassadors.html","Northern Renaissance","The Ambassadors","Hans Holbein the Younger","holbein-ambassadors","Hans Holbein the Younger · 1533 · German, 1497/8–1543. Oil on oak, 81 1/2 × 82 1/2 in. National Gallery, London · The long smear across the floor is a skull, stretched so far that the shape reads only from a sharp angle. · The trick is called anamorphosis. The sitters are Jean de Dinteville, French ambassador to England, and his friend Georges de Selve, a bishop; the skull is a reminder of death."],[16,"/study/art-history/northern-renaissance/northern-europe-1434-1565/hunters-in-the-snow-winter.html","Northern Renaissance","Hunters in the Snow (Winter)","Pieter Bruegel the Elder","bruegel-hunters","Pieter Bruegel the Elder · 1565 · Netherlandish, about 1525/30–1569. Paint on oak panel, 45 3/4 × 63 3/4 in. Kunsthistorisches Museum, Vienna · The view starts on a hilltop and drops into a wide valley, and a few cold colors hold the whole scene together. · Part of a series of six paintings of the seasons, made for the circle of the Antwerp collector Nicolaes Jongelinck."],[17,"/study/oil-vs-acrylic.html","Oil vs Acrylic","Oil vs Acrylic","","rand-1841-tube-patent","For over five centuries oil has been the paint most painters chose, and John Rand's metal tube of 1841 made it easy to carry. Acrylic came out of the plastics industry, first as a solvent paint called Magna, then in water; by 1965 most makers of artists' paint sold a water-based acrylic."],[17,"/study/oil-vs-acrylic/two-paints-compared/two-binders.html","Oil vs Acrylic","Two Binders","","ostade-painter-studio","Paint is pigment, a colored powder, glued in place by a binder that hardens: in oil paint a plant oil that hardens in air, in acrylic tiny plastic droplets in water. · Pieter Bruegel the Elder · The Harvesters · 1565 · The same oil serves for washes so thin the drawing underneath still shows and for strokes thick enough to hide it."],[17,"/study/oil-vs-acrylic/two-paints-compared/two-binders.html","Oil vs Acrylic · Example","The Harvesters","Pieter Bruegel the Elder","thumb/bruegel-harvesters","1565 · The same oil serves for washes so thin the drawing underneath still shows and for strokes thick enough to hide it. · Two Binders"],[17,"/study/oil-vs-acrylic/two-paints-compared/oil-cures.html","Oil vs Acrylic","Oil Cures","","ryder-moonlight-marine-detail","Oil paint does not dry by evaporating; it cures, taking up oxygen until its molecules join into a single solid mesh. Thick paint cures from the top down, so the surface can harden while the paint below is still soft. · Albert Pinkham Ryder · Moonlight Marine · 1870–90 · Ryder built up thick paint layer after layer; wide cracks now cross sky and sea, and the Met reports that the outlines of clouds, sails, and hull have shifted since."],[17,"/study/oil-vs-acrylic/two-paints-compared/oil-cures.html","Oil vs Acrylic · Example","Moonlight Marine","Albert Pinkham Ryder","thumb/ryder-moonlight-marine","1870–90 · Ryder built up thick paint layer after layer; wide cracks now cross sky and sea, and the Met reports that the outlines of clouds, sails, and hull have shifted since. · Oil Cures"],[17,"/study/oil-vs-acrylic/two-paints-compared/acrylic-dries.html","Oil vs Acrylic","Acrylic Dries","","casselmann-film-formation","Acrylic dries by losing water: as it leaves, the plastic droplets crowd together and fuse into a film. The wet binder is milky and turns clear as it dries, so colors often dry slightly darker. · David Nicholson · Early, Still · 2025 · Each flat block set quickly enough for the next to go straight over it, and no color underneath has smudged into the one above."],[17,"/study/oil-vs-acrylic/two-paints-compared/acrylic-dries.html","Oil vs Acrylic · Example","Early, Still","David Nicholson","thumb/dn-early-still","2025 · Each flat block set quickly enough for the next to go straight over it, and no color underneath has smudged into the one above. · Acrylic Dries"],[17,"/study/oil-vs-acrylic/two-paints-compared/open-time.html","Oil vs Acrylic","Open Time","","vermeer-lady-writing-detail","Open time is how long paint stays wet enough to move. Acrylic is dry to the touch in minutes to a few hours, oil in about two days, so oil can be reworked long after acrylic sets. · Claude Monet · Stacks of Wheat (End of Summer) · 1890–91 · The bigger stack's outline, worked wet into wet, is soft and broken against the hills, while sky color Monet added over dry strokes stays in distinct streaks."],[17,"/study/oil-vs-acrylic/two-paints-compared/open-time.html","Oil vs Acrylic · Example","Stacks of Wheat (End of Summer)","Claude Monet","thumb/monet-stacks-of-wheat-end-of-summer","1890–91 · The bigger stack's outline, worked wet into wet, is soft and broken against the hills, while sky color Monet added over dry strokes stays in distinct streaks. · Open Time"],[17,"/study/oil-vs-acrylic/two-paints-compared/impasto.html","Oil vs Acrylic","Impasto","","van-gogh-green-wheat-detail","Impasto is paint laid on thickly enough to hold the shape of each brush or knife stroke. The raised ridges catch light and cast small shadows, so the strokes themselves show. · Rembrandt van Rijn · Lucretia · 1664 · The National Gallery of Art finds extensive palette-knife work in her left cuff, at the right of the picture, and low on her dress, where thick, broken pale patches catch the light."],[17,"/study/oil-vs-acrylic/two-paints-compared/impasto.html","Oil vs Acrylic · Example","Lucretia","Rembrandt van Rijn","thumb/rembrandt-lucretia","1664 · The National Gallery of Art finds extensive palette-knife work in her left cuff, at the right of the picture, and low on her dress, where thick, broken pale patches catch the light. · Impasto"],[17,"/study/oil-vs-acrylic/two-paints-compared/painting-over-dry-paint.html","Oil vs Acrylic","Painting Over Dry Paint","","reni-adoration-detail","Once a layer is dry, new paint no longer mixes with it, so the layer can be changed or covered completely; such changes are called pentimenti, and some show through later. In this unfinished altarpiece, a dog’s head from an earlier idea shows faintly above the angel’s knee. · Titian · Venus with a Mirror · about 1555 · X-rays show a double portrait of a man and a woman underneath, turned on its side; Titian kept the man's jacket and made it her red velvet wrap."],[17,"/study/oil-vs-acrylic/two-paints-compared/painting-over-dry-paint.html","Oil vs Acrylic · Example","Venus with a Mirror","Titian","thumb/titian-venus-with-a-mirror","about 1555 · X-rays show a double portrait of a man and a woman underneath, turned on its side; Titian kept the man's jacket and made it her red velvet wrap. · Painting Over Dry Paint"],[17,"/study/oil-vs-acrylic/two-paints-compared/how-oil-ages.html","Oil vs Acrylic","How Oil Ages","","chaperon-craquelure","Over the decades oil paint stiffens, can yellow, and grows more see-through, so changes the painter covered may start to show. · Diego Velázquez · Philip IV · about 1628 · Velázquez changed the king's legs and cloak and painted over the first versions; their outlines have begun to show through the top layer as faint shapes beside the cloak and legs."],[17,"/study/oil-vs-acrylic/two-paints-compared/how-oil-ages.html","Oil vs Acrylic · Example","Philip IV","Diego Velázquez","thumb/velazquez-philip-iv","about 1628 · Velázquez changed the king's legs and cloak and painted over the first versions; their outlines have begun to show through the top layer as faint shapes beside the cloak and legs. · How Oil Ages"],[18,"/study/pigments-and-materials.html","Pigments and Materials","Pigments and Materials","","amenhotep-palette","The earliest pigments, the colored powders that go into paint, were dug from the ground or burned, and Egyptian blue, fired in a furnace, is the oldest known synthetic pigment. Most laboratory-made colors arrived after 1800; in 1841 an American painter, John Goffe Rand, devised the collapsible metal paint tube."],[18,"/study/pigments-and-materials/what-paintings-are-made-of/earth-pigments.html","Pigments and Materials","Earth Pigments","","sowerby-ochres","Yellow and red earths owe their color to iron minerals mixed into clay and quartz. · Rembrandt van Rijn · Self-Portrait · 1659 · Analysis found red, yellow, and brown ochres, lead white, carbon black, and just traces of vermilion, a mineral red, so the whole picture, flesh included, holds to warm browns, tans, and dull reds."],[18,"/study/pigments-and-materials/what-paintings-are-made-of/earth-pigments.html","Pigments and Materials · Example","Self-Portrait","Rembrandt van Rijn","thumb/rembrandt-self-portrait-1659","1659 · Analysis found red, yellow, and brown ochres, lead white, carbon black, and just traces of vermilion, a mineral red, so the whole picture, flesh included, holds to warm browns, tans, and dull reds. · Earth Pigments"],[18,"/study/pigments-and-materials/what-paintings-are-made-of/reds.html","Pigments and Materials","Reds","","cochineal-plantation","A red could be a mineral, such as vermilion, or a lake: dye from a root or an insect fixed onto a colorless powder so it can be used as paint. · Titian · Venus and Adonis · about 1555–60 · Adonis wears both kinds of red: vermilion in the orange-red sleeve, a lake in the pinker tunic."],[18,"/study/pigments-and-materials/what-paintings-are-made-of/reds.html","Pigments and Materials · Example","Venus and Adonis","Titian","thumb/titian-venus-adonis","about 1555–60 · Adonis wears both kinds of red: vermilion in the orange-red sleeve, a lake in the pinker tunic. · Reds"],[18,"/study/pigments-and-materials/what-paintings-are-made-of/blues.html","Pigments and Materials","Blues","","sowerby-lapis-azurite","Before 1700 painters had only a few blues. Two were crushed minerals: ultramarine, from the stone lapis lazuli, and azurite, from a copper ore. · Johannes Vermeer · Girl with a Pearl Earring · about 1665 · Vermeer painted the turban's blue in top-quality natural ultramarine, with lead white in the light and chalk in the shade, so one blue turns from pale to deep around the head."],[18,"/study/pigments-and-materials/what-paintings-are-made-of/blues.html","Pigments and Materials · Example","Girl with a Pearl Earring","Johannes Vermeer","thumb/vermeer-girl-pearl-earring","about 1665 · Vermeer painted the turban's blue in top-quality natural ultramarine, with lead white in the light and chalk in the shade, so one blue turns from pale to deep around the head. · Blues"],[18,"/study/pigments-and-materials/what-paintings-are-made-of/canvas.html","Pigments and Materials","Canvas","","encyclopedie-peinture-pl4-chassis","Canvas is strong woven cloth, usually linen, stretched taut across a wooden frame; the tension holds it flat and firm enough to take paint. · Titian · The Vendramin Family, venerating a Relic of the True Cross · about 1540–45 · Nearly 9 1/2 feet across, it is one unseamed length of patterned twill, so no seam crosses sky or figures; before the 1800s most large canvases were stitched from strips."],[18,"/study/pigments-and-materials/what-paintings-are-made-of/canvas.html","Pigments and Materials · Example","The Vendramin Family, venerating a Relic of the True Cross","Titian","thumb/titian-vendramin-family","about 1540–45 · Nearly 9 1/2 feet across, it is one unseamed length of patterned twill, so no seam crosses sky or figures; before the 1800s most large canvases were stitched from strips. · Canvas"],[18,"/study/pigments-and-materials/what-paintings-are-made-of/grounds.html","Pigments and Materials","Grounds","","durer-salvator-mundi","A ground is the first coat on a panel or canvas, a smooth, even surface for paint to cling to; its color shows through thin paint. Dürer left the face and hands unfinished, so his drawing still shows there, on the bare ground or through the first thin layers of paint. · Peter Paul Rubens · Samson and Delilah · about 1609–10 · Over a white chalk ground Rubens streaked a yellow-brown layer, then left it uncovered in Delilah's sleeve folds to serve as a warm half-shadow."],[18,"/study/pigments-and-materials/what-paintings-are-made-of/grounds.html","Pigments and Materials · Example","Samson and Delilah","Peter Paul Rubens","thumb/rubens-samson-delilah","about 1609–10 · Over a white chalk ground Rubens streaked a yellow-brown layer, then left it uncovered in Delilah's sleeve folds to serve as a warm half-shadow. · Grounds"],[18,"/study/pigments-and-materials/what-paintings-are-made-of/egg-tempera.html","Pigments and Materials","Egg Tempera","","fei-madonna-detail","In egg tempera yolk holds the pigment, making a fast-drying paint laid on in thin strokes; it was the standard paint for Italian panels through the Middle Ages and early Renaissance. · Giotto · Madonna and Child · about 1310–15 · Giotto set the shadows in a green underpaint before the pink of the flesh went on; it shows through as a cool gray-green on the shaded sides of the faces."],[18,"/study/pigments-and-materials/what-paintings-are-made-of/egg-tempera.html","Pigments and Materials · Example","Madonna and Child","Giotto","thumb/giotto-madonna-child","about 1310–15 · Giotto set the shadows in a green underpaint before the pink of the flesh went on; it shows through as a cool gray-green on the shaded sides of the faces. · Egg Tempera"],[18,"/study/pigments-and-materials/what-paintings-are-made-of/fresco.html","Pigments and Materials","Fresco","","boscoreale-fragment","In fresco the color goes onto lime plaster that is still damp, so it ends up inside the wall instead of on it. · Spanish (Castile) · Lion, from the Chapter House of San Pedro de Arlanza · after 1200 · Painted on a monastery wall after 1200, then removed and fixed to canvas in the early 1900s, the lion still holds its pink, orange, and gray, locked into the plaster."],[18,"/study/pigments-and-materials/what-paintings-are-made-of/fresco.html","Pigments and Materials · Example","Lion, from the Chapter House of San Pedro de Arlanza","Spanish (Castile)","thumb/arlanza-lion","after 1200 · Painted on a monastery wall after 1200, then removed and fixed to canvas in the early 1900s, the lion still holds its pink, orange, and gray, locked into the plaster. · Fresco"],[18,"/study/pigments-and-materials/what-paintings-are-made-of/oil.html","Pigments and Materials","Oil","","stradanus-color-olivi","Oil paint holds its pigment in a drying oil, most often linseed, which sets slowly by absorbing oxygen. · Rogier van der Weyden · The Magdalen Reading · about 1435 · Tests identified linseed oil; the lips melt together where wet paint met wet paint, and the brush pulled through the fur trim before it dried."],[18,"/study/pigments-and-materials/what-paintings-are-made-of/oil.html","Pigments and Materials · Example","The Magdalen Reading","Rogier van der Weyden","thumb/vanderweyden-magdalen-reading","about 1435 · Tests identified linseed oil; the lips melt together where wet paint met wet paint, and the brush pulled through the fur trim before it dried. · Oil"],[18,"/study/pigments-and-materials/what-paintings-are-made-of/watercolor-and-gouache.html","Pigments and Materials","Watercolor and Gouache","","sargent-red-drapery-detail","Watercolor is pigment bound in gum arabic, a gum that dissolves in water, and thinned with water into transparent washes, so its brightness comes from the white paper beneath. · Winslow Homer · The Return, Tynemouth · 1881 · Homer painted the soft pinks of sky and boat with pigments that hold their color in light, and they have survived; many of his other watercolors have lost washes like them."],[18,"/study/pigments-and-materials/what-paintings-are-made-of/watercolor-and-gouache.html","Pigments and Materials · Example","The Return, Tynemouth","Winslow Homer","thumb/homer-return-tynemouth","1881 · Homer painted the soft pinks of sky and boat with pigments that hold their color in light, and they have survived; many of his other watercolors have lost washes like them. · Watercolor and Gouache"],[18,"/study/pigments-and-materials/what-paintings-are-made-of/fading-and-darkening.html","Pigments and Materials","Fading and Darkening","","vangogh-roses","Some pigments shift color over the years as they react with light, with the air, or with the oil that binds them. · Vincent van Gogh · The Bedroom · 1889 · Analysts found specks of red lake in the doors, suspected to have been violet and now light blue, and geranium lake, probably faded, in the floor."],[18,"/study/pigments-and-materials/what-paintings-are-made-of/fading-and-darkening.html","Pigments and Materials · Example","The Bedroom","Vincent van Gogh","thumb/vangogh-bedroom","1889 · Analysts found specks of red lake in the doors, suspected to have been violet and now light blue, and geranium lake, probably faded, in the floor. · Fading and Darkening"],[19,"/study/art-history/post-impressionism.html","Post-Impressionism · Overview","What to Look For","","seurat-circus","Post-Impressionism is the label given, after the fact, to painters working in France from about 1884 to 1906 who started from Impressionism and went past it. They kept its bright color and visible brushwork, and used them for something other than recording light: solid structure, strong feeling, flat color, or pattern. · Georges Seurat · The Circus · 1891"],[19,"/study/art-history/post-impressionism/france-1884-1906/bathers-at-asnieres.html","Post-Impressionism","Bathers at Asnières","Georges Seurat","seurat-bathers","Georges Seurat · 1884 · French, 1859–1891. Oil on canvas, 79 1/4 × 118 in. The National Gallery, London · Seurat built the surface from visible dabs, flicks, and crisscross strokes and held every figure as still as a statue. Most of the large figures sit in profile inside unbroken outlines, so each reads as a fixed shape. · Rejected by the official Salon and shown instead at the first Salon des Indépendants, a jury-free exhibition, in 1884. Seurat later reworked the orange hat in dots of yellow and blue."],[19,"/study/art-history/post-impressionism/france-1884-1906/the-basket-of-apples.html","Post-Impressionism","The Basket of Apples","Paul Cézanne","cezanne-basket","Paul Cézanne · about 1893 · French, 1839–1906. Oil on canvas, 25 1/2 × 31 1/2 in. The Art Institute of Chicago · Cézanne painted the table as if from two places at once: its front edge sits lower on the left of the cloth than on the right. The basket tips forward and the bottle leans left, so each object looks as if seen from a slightly different spot. · Shown at Cézanne's first one-man exhibition, at the Vollard gallery in Paris, 1895."],[19,"/study/art-history/post-impressionism/france-1884-1906/mont-sainte-victoire.html","Post-Impressionism","Mont Sainte-Victoire","Paul Cézanne","cezanne-sainte-victoire","Paul Cézanne · 1902–04 · Oil on canvas, 28 3/4 × 36 1/4 in. Philadelphia Museum of Art · Cézanne made the valley and the sky from the same patches of parallel brushstrokes, and color alone tells near from far: warm ochres and yellows in the plain, blue and violet in the mountain and sky. · The mountain stands near Aix-en-Provence, Cézanne's hometown, and he painted it again and again in his last years."],[19,"/study/art-history/post-impressionism/france-1884-1906/the-night-cafe.html","Post-Impressionism","The Night Café","Vincent van Gogh","vangogh-night-cafe","Vincent van Gogh · 1888 · Dutch, 1853–1890. Oil on canvas, 28 1/2 × 36 1/4 in. Yale University Art Gallery, New Haven · Van Gogh set blood-red walls against a green ceiling and billiard table so that the colors clash. Short yellow and orange strokes ring each gas lamp, so its halo reads as glare. · Shows the Café de l'Alcazar in Arles, where Van Gogh took his meals; he wrote that its red and green express “the terrible passions of humanity.”"],[19,"/study/art-history/post-impressionism/france-1884-1906/the-starry-night.html","Post-Impressionism","The Starry Night","Vincent van Gogh","vangogh-starry-night","Vincent van Gogh · 1889 · Oil on canvas, 29 × 36 1/4 in. The Museum of Modern Art, New York · Van Gogh made the sky from short visible strokes laid end to end in long curling lines. Two spirals turn in the center of the sky, and the strokes inside bend with them, so the paint itself shows the motion. · Based on the view from Van Gogh's window at the asylum of Saint-Rémy and painted in daytime sessions; the village was added from other views."],[19,"/study/art-history/post-impressionism/france-1884-1906/vision-of-the-sermon-jacob-wrestling-with-the-angel.html","Post-Impressionism","Vision of the Sermon (Jacob Wrestling with the Angel)","Paul Gauguin","gauguin-vision","Paul Gauguin · 1888 · French, 1848–1903. Oil on canvas, 28 1/2 × 35 3/4 in. Scottish National Gallery, Edinburgh · Gauguin painted the ground as a flat field of pure red and set every shape on it inside a dark outline. The cow and wrestlers are small, as if far away, but the flat red gives them no distance from the large heads in front. · Painted at Pont-Aven in Brittany. Breton women are praying after a sermon about Jacob wrestling the angel; Gauguin wrote that the fight exists only in their imagination."],[19,"/study/art-history/post-impressionism/france-1884-1906/at-the-moulin-rouge.html","Post-Impressionism","At the Moulin Rouge","Henri de Toulouse-Lautrec","lautrec-moulin-rouge","Henri de Toulouse-Lautrec · 1892–95 · French, 1864–1901. Oil on canvas, 48 1/2 × 55 1/2 in. The Art Institute of Chicago · Toulouse-Lautrec cut the scene off at its edges: a railing slices the lower left, and the right edge crops a face turned green by electric light. That pale face, beside yellow hair and red lips, is the brightest spot, so it pulls the eye to the cropped edge. · Lautrec's own friends fill the table at the Moulin Rouge, which was built for electric light; he is in the center background beside his cousin."],[20,"/study/art-history/realism.html","Realism · Overview","What to Look For","","menzel-iron-rolling-mill","Realism painted ordinary people and everyday work as they were, at the size and seriousness once kept for history, myth, and religion. It began in France around 1848 and spread across Europe and to the United States. · Adolph Menzel · The Iron Rolling Mill · 1872–75"],[20,"/study/art-history/realism/europe-and-the-united-states-1849-1875/a-burial-at-ornans.html","Realism","A Burial at Ornans","Gustave Courbet","courbet-burial-at-ornans","Gustave Courbet · 1849–50 · French, 1819–1877. Oil on canvas, 124 × 263 in. Musée d'Orsay, Paris · Courbet painted ordinary villagers at life size, on a canvas about 22 feet wide, in heavy paint and deep blacks. The mourners' heads run in one long row at nearly the same height, so no single figure takes the lead. · A funeral in Courbet's hometown of Ornans, with townspeople as the sitters; shown at the Salon of 1850–51."],[20,"/study/art-history/realism/europe-and-the-united-states-1849-1875/the-horse-fair.html","Realism","The Horse Fair","Rosa Bonheur","bonheur-horse-fair","Rosa Bonheur · 1852–55 · French, 1822–1899. Oil on canvas, 96 1/4 × 199 1/2 in. The Metropolitan Museum of Art, New York · Bonheur set a stream of horses moving from left to right and painted muscles, hooves, and manes in close detail. Two rear up at the center, one black and one white, where the line peaks. · A horse market on a Paris boulevard, first shown at the Salon of 1853 and retouched by the artist in 1855."],[20,"/study/art-history/realism/europe-and-the-united-states-1849-1875/the-gleaners.html","Realism","The Gleaners","Jean-François Millet","millet-gleaners","Jean-François Millet · 1857 · French, 1814–1875. Oil on canvas, 32 3/4 × 43 1/4 in. Musée d'Orsay, Paris · Millet set three stooping women in a low run of curves across the foreground, lit by late sun that makes their backs look round and solid. The haystacks and cart far behind are pale and small, so the field looks deep. · Gleaners gathered the grain left in the field after the harvest; shown at the Salon of 1857."],[20,"/study/art-history/realism/europe-and-the-united-states-1849-1875/the-third-class-carriage.html","Realism","The Third-Class Carriage","Honoré Daumier","daumier-third-class-carriage","Honoré Daumier · 1864 · French, 1808–1879. Oil on canvas, 25 3/4 × 35 1/2 in. The Metropolitan Museum of Art, New York · Daumier ringed the figures with dark outlines and left the canvas unfinished. A faint grid of ruled lines still shows through the thin paint. · The grid was used to transfer the design onto the canvas; a finished version is in the National Gallery of Canada, Ottawa."],[20,"/study/art-history/realism/europe-and-the-united-states-1849-1875/the-veteran-in-a-new-field.html","Realism","The Veteran in a New Field","Winslow Homer","homer-veteran-new-field","Winslow Homer · 1865 · American, 1836–1910. Oil on canvas, 24 1/4 × 38 1/4 in. The Metropolitan Museum of Art, New York · Homer reduced the picture to three bands: blue sky, a wall of golden wheat, and cut stalks in front. The wheat rises to one nearly straight edge with no distance behind it, so it reads as a flat wall. · Painted after the Civil War ended; the discarded Union jacket and canteen show that the farmer is a returned soldier."],[20,"/study/art-history/realism/europe-and-the-united-states-1849-1875/barge-haulers-on-the-volga.html","Realism","Barge Haulers on the Volga","Ilya Repin","repin-barge-haulers","Ilya Repin · 1870–73 · 1844–1930. Oil on canvas, 51 3/4 × 110 3/4 in. State Russian Museum, St. Petersburg · Repin joined eleven men in harness into one long chain from the left toward the ship at the right. Against bright, flat sand and sky, the dark group reads as one shape. · The figures are based on portraits of real haulers, drawn on two trips to the Volga."],[20,"/study/art-history/realism/europe-and-the-united-states-1849-1875/the-gross-clinic.html","Realism","The Gross Clinic","Thomas Eakins","eakins-gross-clinic","Thomas Eakins · 1875 · American, 1844–1916. Oil on canvas, 96 × 78 in. Philadelphia Museum of Art and Pennsylvania Academy of the Fine Arts · Eakins set bright red on the surgeon's fingers and scalpel against browns and blacks. One strong light from above runs from his forehead down to the red hand, while the students behind sink into shadow. · Made for the 1876 Centennial Exhibition, where the art jury rejected it; also titled Portrait of Dr. Samuel D. Gross."],[21,"/study/art-history/rococo.html","Rococo · Overview","What to Look For","","fragonard-meeting","Rococo is the light, curving, pastel style of Paris and Venice in the decades after 1715. · Jean-Honoré Fragonard · The Progress of Love: The Meeting · 1771–72"],[21,"/study/art-history/rococo/france-and-venice-1717-1772/pilgrimage-to-the-island-of-cythera.html","Rococo","Pilgrimage to the Island of Cythera","Antoine Watteau","watteau-cythera","Antoine Watteau · 1717 · French, 1684–1721. Oil on canvas, 50 3/4 × 76 1/2 in. Musée du Louvre, Paris · Watteau let a hillside of couples dissolve into a hazy pink and blue distance. · Delivered to the Paris Academy in 1717 as Watteau's reception piece and registered as a fête galante, an elegant party out of doors."],[21,"/study/art-history/rococo/france-and-venice-1717-1772/gustavus-hamilton-second-viscount-boyne-in-masquerade-costume.html","Rococo","Gustavus Hamilton, Second Viscount Boyne, in Masquerade Costume","Rosalba Carriera","carriera-boyne","Rosalba Carriera · 1730–31 · Italian, 1673–1757. Pastel on paper, laid down on canvas, 22 1/4 × 16 7/8 in. The Metropolitan Museum of Art, New York · Carriera used pastel to give the whole surface a soft, powdery skin. · An Irish visitor in Venetian Carnival dress: veil, tricorne, and short cape."],[21,"/study/art-history/rococo/france-and-venice-1717-1772/the-triumph-of-venus.html","Rococo","The Triumph of Venus","François Boucher","boucher-triumph-venus","François Boucher · 1740 · French, 1703–1770. Oil on canvas, 51 1/4 × 63 3/4 in. Nationalmuseum, Stockholm · Boucher turned the composition into one great spiral of pink flesh, striped silk, and blue-green sea. · Venus, seated on a shell, attended by sea nymphs and tritons; exhibited at the 1740 Paris Salon."],[21,"/study/art-history/rococo/france-and-venice-1717-1772/allegory-of-the-planets-and-continents.html","Rococo","Allegory of the Planets and Continents","Giovanni Battista Tiepolo","tiepolo-planets","Giovanni Battista Tiepolo · 1752 · Italian, 1696–1770. Oil on canvas, 73 × 54 7/8 in. The Metropolitan Museum of Art, New York · Tiepolo painted a ceiling in miniature: figures seen from below crowd the four edges of a wide pale sky. · Presented in 1752 as a proposed design for the Würzburg palace's staircase ceiling."],[21,"/study/art-history/rococo/france-and-venice-1717-1772/madame-de-pompadour.html","Rococo","Madame de Pompadour","François Boucher","boucher-pompadour","François Boucher · 1756 · Oil on canvas, 80 3/4 × 63 1/2 in. Alte Pinakothek, Munich · Boucher laid pattern on pattern: roses on sea-green satin, against a gold curtain and a carved gilt mirror. · Louis XV's official mistress, shown with the books, letters, music, and drawings of a cultivated life."],[21,"/study/art-history/rococo/france-and-venice-1717-1772/the-swing.html","Rococo","The Swing","Jean-Honoré Fragonard","fragonard-swing","Jean-Honoré Fragonard · about 1767–68 · French, 1732–1806. Oil on canvas, 32 × 25 1/4 in. The Wallace Collection, London · Fragonard sent one shaft of sunlight onto a pink dress and let the garden sink into blue-green shadow. · A young woman on a swing, a man hidden in the bushes below, and a stone cupid with a finger to his lips."],[21,"/study/art-history/rococo/france-and-venice-1717-1772/young-girl-reading.html","Rococo","Young Girl Reading","Jean-Honoré Fragonard","fragonard-girl-reading","Jean-Honoré Fragonard · about 1769 · Oil on canvas, 31 15/16 × 25 1/2 in. National Gallery of Art, Washington · Fragonard painted the goldenrod dress and the cushion in loose, open strokes and left the strokes visible. · One of the fantasy figures, a set of half-length portraits in costume."],[22,"/study/art-history/romanticism.html","Romanticism · Overview","What to Look For","","friedrich-monk-by-the-sea","Romanticism was a shift in art and literature at its height from about 1780 to 1830. Artists in Britain, Spain, Germany, and France moved away from classical calm and built their pictures around strong emotion, dreams and fears, and the force of nature. · Caspar David Friedrich · The Monk by the Sea · 1808–10"],[22,"/study/art-history/romanticism/europe-1781-1844/the-nightmare.html","Romanticism","The Nightmare","Henry Fuseli","fuseli-nightmare","Henry Fuseli · 1781 · Swiss, 1741–1825. Oil on canvas, 40 × 50 in. Detroit Institute of Arts · Fuseli stretched a limp white body across a dark room and left the creature and the horse half lost in shadow. · First shown at the Royal Academy in London in 1782."],[22,"/study/art-history/romanticism/europe-1781-1844/the-third-of-may-1808.html","Romanticism","The Third of May 1808","Francisco de Goya","goya-third-of-may","Francisco de Goya · 1814 · Spanish, 1746–1828. Oil on canvas, 105 1/2 × 136 1/2 in. Museo Nacional del Prado, Madrid · Goya lit the scene from one lantern on the ground and turned its light on a man in a white shirt. The soldiers are a row of dark backs with no faces, so the eye goes straight to him. · Shows the executions French troops carried out in Madrid after the uprising of May 2, 1808; painted six years later."],[22,"/study/art-history/romanticism/europe-1781-1844/wanderer-above-the-sea-of-fog.html","Romanticism","Wanderer above the Sea of Fog","Caspar David Friedrich","friedrich-wanderer","Caspar David Friedrich · about 1817 · German, 1774–1840. Oil on canvas, 37 1/4 × 29 1/2 in. Hamburger Kunsthalle, Hamburg · Friedrich stood a single dark figure dead center, seen from behind. Distant ridges slope down from both sides and meet at his chest, so the eye slides along them to him. · A figure seen from behind, like this one, is called a Rückenfigur."],[22,"/study/art-history/romanticism/europe-1781-1844/the-raft-of-the-medusa.html","Romanticism","The Raft of the Medusa","Théodore Géricault","gericault-raft-medusa","Théodore Géricault · 1818–19 · French, 1791–1824. Oil on canvas, 193 1/4 × 282 in. Musée du Louvre, Paris · Géricault stacked the bodies into a pyramid climbing from lower left to a man waving a cloth at upper right. Raised arms all reach the same way, pulling the eye to the top. · The picture records the 1816 wreck of a frigate off Senegal. About 150 people went onto a raft, and 15 were alive when a ship found them 12 days later."],[22,"/study/art-history/romanticism/europe-1781-1844/the-hay-wain.html","Romanticism","The Hay Wain","John Constable","constable-hay-wain","John Constable · 1821 · British, 1776–1837. Oil on canvas, 51 1/4 × 73 in. The National Gallery, London · Constable built the foliage from many separate strokes and flecked the water and leaves with small dabs of white. Laid over darker paint, the dabs read as light catching the surface. · The millpond is at Flatford on the River Stour; the work was done in the artist's London studio."],[22,"/study/art-history/romanticism/europe-1781-1844/liberty-leading-the-people.html","Romanticism","Liberty Leading the People","Eugène Delacroix","delacroix-liberty-leading","Eugène Delacroix · 1830 · French, 1798–1863. Oil on canvas, 102 1/4 × 128 in. Musée du Louvre, Paris · Delacroix echoed the flag's red, white, and blue in small notes across a mostly gray and brown picture. The jacket and sash on the figure kneeling at Liberty's feet repeat that blue and red, tying him to it. · Painted in the autumn of 1830, after the July Revolution in Paris, and also called A Barricade."],[22,"/study/art-history/romanticism/europe-1781-1844/rain-steam-and-speed-the-great-western-railway.html","Romanticism","Rain, Steam, and Speed – The Great Western Railway","J.M.W. Turner","turner-rain-steam-speed","J.M.W. Turner · 1844 · British, 1775–1851. Oil on canvas, 35 3/4 × 48 in. The National Gallery, London · Turner blurred almost everything and kept his sharpest edge for the engine. Creams, golds, and pale blues run together with no clear horizon, so the distance reads as one sheet of haze. · A train crosses the Maidenhead railway bridge over the Thames; the bridge was finished in 1838."],[23,"/study/value-and-light.html","Value and Light","Value and Light","","cross-fig21","Leonardo da Vinci saw light and shade as what lets a flat picture look solid. In the 1800s, drawing manuals by Mary Merrifield and Anson Cross taught the same ideas with plain white models."],[23,"/study/value-and-light/light-shade-and-form/the-value-scale.html","Value and Light","The Value Scale","","merrifield-pl02-scale","Value is how light or dark something is, whatever its color. A value scale lays it out in steps from white to black, so any tone can be matched to a step. · Jean-Auguste-Dominique Ingres · Odalisque in Grisaille · about 1824–34 · Ingres painted this unfinished, smaller repeat of his 1814 Grande Odalisque almost entirely in grays, so value does nearly all the work of building the body."],[23,"/study/value-and-light/light-shade-and-form/the-value-scale.html","Value and Light · Example","Odalisque in Grisaille","Jean-Auguste-Dominique Ingres","thumb/ingres-odalisque-grisaille","about 1824–34 · Ingres painted this unfinished, smaller repeat of his 1814 Grande Odalisque almost entirely in grays, so value does nearly all the work of building the body. · The Value Scale"],[23,"/study/value-and-light/light-shade-and-form/high-and-low-key.html","Value and Light","High and Low Key","","morisot-summers-day","Key is where a picture's values mostly fall. A high-key picture, mostly lights, looks flooded with light; a low-key one, mostly darks, makes its few lights stand out strongly. · Rembrandt van Rijn · Philosopher in Meditation · 1632 · Rembrandt gave most of the panel to darkness, so the window daylight reaching the old man and one small fire at the right glow against it."],[23,"/study/value-and-light/light-shade-and-form/high-and-low-key.html","Value and Light · Example","Philosopher in Meditation","Rembrandt van Rijn","thumb/rembrandt-philosopher-in-meditation","1632 · Rembrandt gave most of the panel to darkness, so the window daylight reaching the old man and one small fire at the right glow against it. · High and Low Key"],[23,"/study/value-and-light/light-shade-and-form/the-light-and-shadow-sequence.html","Value and Light","The Light and Shadow Sequence","","merrifield-pl09","A rounded form turns away from a single light bit by bit, so its values run in a set order: highlight, light side, halftone (a middle tone), darkest shadow band, reflected light bounced into the shadow, then the shadow on the ground. · Juan Sánchez Cotán · Quince, Cabbage, Melon and Cucumber · about 1602 · Sánchez Cotán let the lit fronts of the quince and cabbage give way to deep shadow on the sides away from the light, so each looks round against the dark opening."],[23,"/study/value-and-light/light-shade-and-form/the-light-and-shadow-sequence.html","Value and Light · Example","Quince, Cabbage, Melon and Cucumber","Juan Sánchez Cotán","thumb/sanchez-cotan-quince-cabbage","about 1602 · Sánchez Cotán let the lit fronts of the quince and cabbage give way to deep shadow on the sides away from the light, so each looks round against the dark opening. · The Light and Shadow Sequence"],[23,"/study/value-and-light/light-shade-and-form/cast-shadows.html","Value and Light","Cast Shadows","","merrifield-pl03","When an object stands in the light's path, it throws its shape onto nearby surfaces as a cast shadow. · Vilhelm Hammershøi · Dust Motes Dancing in the Sunbeams · 1901 · The window bars block parts of the sunbeams, so the patches of sun on the floor carry the window's grid of shadow."],[23,"/study/value-and-light/light-shade-and-form/cast-shadows.html","Value and Light · Example","Dust Motes Dancing in the Sunbeams","Vilhelm Hammershøi","thumb/hammershoi-dust-motes","1901 · The window bars block parts of the sunbeams, so the patches of sun on the floor carry the window's grid of shadow. · Cast Shadows"],[23,"/study/value-and-light/light-shade-and-form/direction-of-light.html","Value and Light","Direction of Light","","cross-figs-08-10-11","Light reaches only the surfaces turned toward it, so its direction sets how a subject divides into lit and shaded areas, and with that how solid it looks. · Pierre-Paul Prud'hon · Study of Drapery · about 1813 · Light from one side catches the cloth's ridges in white chalk, the deepest folds go to black, and the blue paper is the middle value, so each fold reads as rounded."],[23,"/study/value-and-light/light-shade-and-form/direction-of-light.html","Value and Light · Example","Study of Drapery","Pierre-Paul Prud'hon","thumb/prudhon-blue-paper","about 1813 · Light from one side catches the cloth's ridges in white chalk, the deepest folds go to black, and the blue paper is the middle value, so each fold reads as rounded. · Direction of Light"],[23,"/study/value-and-light/light-shade-and-form/edges.html","Value and Light","Edges","","cross-fig13","An edge is where one value meets another: hard when the change is sharp, soft when it blends, lost when the values match. Hard edges catch the eye; soft and lost ones let a form sink into its surroundings. · Diego Velázquez · Juan de Pareja · 1650 · Velázquez kept the white collar crisp and let the beard melt into the hair and the dark coat into the dark background, so the collar and lit face stand forward."],[23,"/study/value-and-light/light-shade-and-form/edges.html","Value and Light · Example","Juan de Pareja","Diego Velázquez","thumb/velazquez-juan-de-pareja","1650 · Velázquez kept the white collar crisp and let the beard melt into the hair and the dark coat into the dark background, so the collar and lit face stand forward. · Edges"],[23,"/study/value-and-light/light-shade-and-form/chiaroscuro.html","Value and Light","Chiaroscuro","","rembrandt-aristotle-detail","Chiaroscuro (Italian for \"light-dark\") is the balance and pattern of light and shade across a whole picture, arranged as one design. The shading makes forms look solid, and lights set against darks make each other stand out. · Leonardo da Vinci · The Virgin of the Rocks · about 1491/2–9 and 1506–8 · The figures come out of the dark grotto by soft degrees, with no hard outline at the Virgin's temples or nose, an effect later called sfumato, from the Italian for \"to turn to smoke\"."],[23,"/study/value-and-light/light-shade-and-form/chiaroscuro.html","Value and Light · Example","The Virgin of the Rocks","Leonardo da Vinci","thumb/leonardo-virgin-of-the-rocks","about 1491/2–9 and 1506–8 · The figures come out of the dark grotto by soft degrees, with no hard outline at the Virgin's temples or nose, an effect later called sfumato, from the Italian for \"to turn to smoke\". · Chiaroscuro"]]};
